(window.KOTOBA_HK=window.KOTOBA_HK||{})[34]={"n":34,"S":[{"id":"l34a","ti":[[["吉四六さん","きっちょむさん"],["と","と"],["空","そら"],["を","を"],["飛ぶ","とぶ","飛ぶ",5],["かご","かご"]]],"tt":{"az":"Kicçom-san və uçan səbət","en":"Kicchomu and the Flying Basket","ru":"Киттёму и летающая корзина"},"P":[{"t":[[["むかしむかし","むかしむかし"],["、"],["ある","ある","ある(連体詞)"],["村","むら"],["に","に"],["、"],["吉四六さん","きっちょむさん"],["と","と"],["いう","いう","いう",5],["頭","あたま"],["の","の"],["いい","いい"],["男","おとこ"],["が","が"],["いました","いました","いる",2],["。"],["吉四六さん","きっちょむさん"],["は","は"],["、"],["いつ","いつ"],["も","も"],["おもしろい","おもしろい"],["こと","こと"],["を","を"],["考えて","かんがえて","考える",3],["、"],["村","むら"],["の","の"],["人たち","ひとたち"],["を","を"],["笑わせました","わらわせました","笑う",16],["。"],["でも","でも"],["、"],["村","むら"],["に","に"],["は","は"],["、"],["とても","とても"],["いじ","いじ"],["わるな","わるな","わる",1],["地主","じぬし"],["が","が"],["いました","いました","いる",2],["。"],["地主","じぬし"],["は","は"],["毎日","まいにち"],["、"],["村","むら"],["の","の"],["人たち","ひとたち"],["を","を"],["朝","あさ"],["早く","はやく"],["から","から"],["働かせました","はたらかせました","働く",16],["。"]]],"tr":{"az":"Biri var idi, biri yox idi, bir kənddə Kicçom adlı ağıllı bir kişi yaşayırdı. Kicçom həmişə maraqlı şeylər fikirləşib kəndliləri güldürürdü. Amma kənddə çox zalım bir torpaq sahibi vardı. O, kəndliləri hər gün səhər tezdən işləməyə məcbur edirdi.","en":"Long ago, in a village, there lived a clever man named Kicchomu. He always thought of amusing things and made the villagers laugh. But the village had a very mean landlord. Every day, he made the villagers work from early morning.","ru":"Давным-давно в одной деревне жил умный человек по имени Киттёму. Он всегда придумывал что-нибудь забавное и смешил жителей. Но в деревне был очень злой помещик. Каждый день он заставлял крестьян работать с раннего утра."}},{"t":[[["ある日","あるひ"],["、"],["地主","じぬし"],["は","は"],["吉四六さん","きっちょむさん"],["を","を"],["家","いえ"],["に","に"],["呼びました","よびました","呼ぶ",2],["。"],["そして","そして"],["、"],["大きな","おおきな"],["竹","たけ"],["の","の"],["かご","かご"],["を","を"],["見せました","みせました","見せる",2],["。"],["「"],["この","この"],["かご","かご"],["を","を"],["空","そら"],["に","に"],["飛ばせ","とばせ","飛ぶ",100],["。"],["できなかったら","できなかったら","できる",101],["、"],["一","いち"],["日中","にちなか"],["働け","はたらけ","働ける",10],["」"],["と","と"],["命令","めいれい"],["しました","しました","する",2],["。"],["吉四六さん","きっちょむさん"],["は","は"],["少し","すこし"],["考えて","かんがえて","考える",3],["、"],["「"],["三日","みっか"],["だけ","だけ"],["準備","じゅんび"],["を","を"],["させていただけません","させていただけません","する",102],["か","か"],["」"],["と","と"],["頼みました","たのみました","頼む",2],["。"]]],"tr":{"az":"Bir gün torpaq sahibi Kicçomu evinə çağırdı. Sonra ona böyük bir bambuk səbət göstərdi. «Bu səbəti göyə uçur! Bacarmasan, bütün günü işləyəcəksən!» deyə əmr etdi. Kicçom bir az düşünüb «Hazırlaşmaq üçün mənə üç gün icazə verə bilərsinizmi?» deyə xahiş etdi.","en":"One day, the landlord called Kicchomu to his house. He showed him a large bamboo basket. “Make this basket fly into the sky. If you cannot, work all day!” he ordered. Kicchomu thought for a moment and asked, “Could you allow me three days to prepare?”","ru":"Однажды помещик позвал Киттёму к себе домой. Затем он показал ему большую бамбуковую корзину. «Заставь эту корзину летать! Если не сможешь, будешь работать весь день!» – приказал он. Киттёму немного подумал и попросил: «Не могли бы вы дать мне три дня на подготовку?»"}},{"t":[[["吉四六さん","きっちょむさん"],["は","は"],["村","むら"],["へ","へ"],["帰り","かえり","帰る",10],["、"],["友達","ともだち"],["に","に"],["「"],["ちょっと","ちょっと"],["手伝ってもらえません","てつだってもらえません","手伝う",6],["か","か"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["友達","ともだち"],["に","に"],["長い","ながい"],["ひも","ひも"],["を","を"],["作ってもらい","つくってもらい","作る",103],["、"],["子どもたち","こどもたち"],["に","に"],["は","は"],["紙","かみ"],["の","の"],["鳥","とり"],["を","を"],["作らせました","つくらせました","作る",16],["。"],["子どもたち","こどもたち"],["は","は"],["楽し","たのし","楽しい"],["そうに","そうに","そう",8],["働きました","はたらきました","働く",2],["。"],["でも","でも"],["、"],["一人","ひとり"],["の","の"],["男の子","おとこのこ"],["は","は"],["父親","ちちおや"],["に","に"],["勉強","べんきょう"],["させられていた","させられていた","する",104],["の","の"],["で","で","だ"],["、"],["来られませんでした","こられませんでした","来る",53],["。"]]],"tr":{"az":"Kicçom kəndə qayıdıb dostuna «Mənə bir az kömək edə bilərsənmi?» dedi. Dostundan uzun kəndir düzəltməsini xahiş etdi, uşaqlara isə kağızdan quşlar düzəltdirdi. Uşaqlar həvəslə işlədilər. Amma bir oğlan atası tərəfindən dərs oxumağa məcbur edildiyi üçün gələ bilmədi.","en":"Kicchomu returned to the village and said to a friend, “Could you help me a little?” He had his friend make a long rope and made the children create paper birds. The children worked happily. But one boy could not come because his father was making him study.","ru":"Киттёму вернулся в деревню и сказал другу: «Не мог бы ты немного помочь мне?» Он попросил друга сделать длинную верёвку, а детям велел смастерить бумажных птиц. Дети работали с удовольствием. Но один мальчик не смог прийти, потому что отец заставлял его учиться."}},{"t":[[["三日目","みっかめ"],["の","の"],["朝","あさ"],["、"],["吉四六さん","きっちょむさん"],["は","は"],["かご","かご"],["を","を"],["高い","たかい"],["木","き"],["の","の"],["下","した"],["へ","へ"],["運びました","はこびました","運ぶ",2],["。"],["木","き"],["の","の"],["上","うえ"],["に","に"],["は","は"],["長い","ながい"],["ひも","ひも"],["が","が"],["あり","あり","ある",10],["、"],["かご","かご"],["と","と"],["つながっていました","つながっていました","つながる",15],["。"],["吉四六さん","きっちょむさん"],["は","は"],["友達","ともだち"],["に","に"],["「"],["合図","あいず"],["を","を"],["したら","したら","する",44],["、"],["ひも","ひも"],["を","を"],["引いてください","ひいてください","引く",35],["」"],["と","と"],["頼みました","たのみました","頼む",2],["。"],["村","むら"],["の","の"],["人たち","ひとたち"],["は","は"],["、"],["何","なに"],["が","が"],["始まる","はじまる","始まる",5],["の","の"],["か","か"],["知りたくて","しりたくて","知る",105],["、"],["集まってきました","あつまってきました","集まる",23],["。"]]],"tr":{"az":"Üçüncü gün səhər Kicçom səbəti hündür bir ağacın altına apardı. Ağacın yuxarısında səbətə bağlanmış uzun bir kəndir vardı. Kicçom dostundan «İşarə verəndə kəndiri çək, zəhmət olmasa» deyə xahiş etdi. Nə baş verəcəyini bilmək istəyən kəndlilər ora toplaşdılar.","en":"On the third morning, Kicchomu carried the basket beneath a tall tree. A long rope ran over the tree and was connected to the basket. He asked his friend, “Please pull the rope when I give the signal.” The villagers gathered, curious to see what would happen.","ru":"Утром третьего дня Киттёму отнёс корзину под высокое дерево. Через верхние ветви проходила длинная верёвка, привязанная к корзине. Он попросил друга: «Когда я подам знак, пожалуйста, потяни за верёвку». Жители собрались, потому что хотели узнать, что произойдёт."}},{"t":[[["地主","じぬし"],["が","が"],["来る","くる","来る",5],["と","と"],["、"],["吉四六さん","きっちょむさん"],["は","は"],["大きな","おおきな"],["声","こえ"],["で","で"],["「"],["空","そら"],["の","の"],["鳥","とり"],["よ","よ"],["、"],["この","この"],["かご","かご"],["を","を"],["飛ばせ","とばせ","飛ぶ",100],["！"],["」"],["と","と"],["叫びました","さけびました","叫ぶ",2],["。"],["する","する","する",5],["と","と"],["、"],["かご","かご"],["が","が"],["ゆっくり","ゆっくり"],["上","うえ"],["へ","へ"],["動きました","うごきました","動く",2],["。"],["紙","かみ"],["の","の"],["鳥","とり"],["も","も"],["風","かぜ"],["で","で"],["ひらひら","ひらひら"],["飛びました","とびました","飛ぶ",2],["。"],["地主","じぬし"],["は","は"],["目","め"],["を","を"],["丸く","まるく","丸い"],["して","して","する",3],["、"],["「"],["本当","ほんとう"],["に","に"],["飛んだ","とんだ","飛ぶ"],["！"],["」"],["と","と"],["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Torpaq sahibi gələndə Kicçom ucadan «Ey göydəki quşlar, bu səbəti uçurun!» deyə qışqırdı. Elə həmin an səbət yavaş-yavaş yuxarı qalxdı. Kağız quşlar da küləkdə uçuşmağa başladı. Torpaq sahibi gözlərini bərəldib «Doğrudan da uçdu!» dedi.","en":"When the landlord arrived, Kicchomu shouted, “Birds of the sky, make this basket fly!” At once, the basket slowly rose. The paper birds fluttered in the wind. The landlord opened his eyes wide and cried, “It really flew!”","ru":"Когда пришёл помещик, Киттёму громко крикнул: «Птицы небесные, заставьте эту корзину лететь!» И тут корзина медленно поднялась вверх. Бумажные птицы тоже запорхали на ветру. Помещик широко раскрыл глаза и воскликнул: «Она действительно полетела!»"}},{"t":[[["地主","じぬし"],["は","は"],["自分","じぶん"],["も","も"],["空","そら"],["へ","へ"],["行きたく","いきたく","行く",30],["なりました","なりました","なる",2],["。"],["「"],["今度","こんど"],["は","は"],["わし","わし"],["を","を"],["乗せろ","のせろ","乗せる",10],["！"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["吉四六さん","きっちょむさん"],["は","は"],["困った","こまった","困る",0],["顔","かお"],["を","を"],["して","して","する",3],["、"],["「"],["それ","それ"],["なら","なら","だ"],["、"],["村","むら"],["の","の"],["人たち","ひとたち"],["を","を"],["一週間","いっしゅうかん"],["休ませていただけません","やすませていただけません","休む",102],["か","か"],["」"],["と","と"],["聞きました","ききました","聞く",2],["。"],["地主","じぬし"],["は","は"],["早く","はやく","早い"],["空","そら"],["へ","へ"],["行きたかった","いきたかった","行く",21],["の","の"],["で","で","だ"],["、"],["「"],["いい","いい"],["ぞ","ぞ"],["。"],["早く","はやく","早い"],["し","し","する",10],["なさい","なさい","なさる",10],["！"],["」"],["と","と"],["答えました","こたえました","答える",2],["。"]]],"tr":{"az":"Torpaq sahibi özü də göyə qalxmaq istədi. «Bu dəfə məni mindir!» dedi. Kicçom özünü çətin vəziyyətdəymiş kimi göstərib «Onda kəndlilərə bir həftə istirahət etməyə icazə verərsinizmi?» deyə soruşdu. Torpaq sahibi tez göyə qalxmaq istədiyi üçün «Yaxşı! Tez ol!» cavabını verdi.","en":"The landlord wanted to go into the sky himself. “Let me ride in it next!” he said. Kicchomu made a troubled face and asked, “In that case, could you allow the villagers to rest for a week?” The landlord was eager to fly, so he replied, “Fine! Hurry up!”","ru":"Помещик тоже захотел подняться в небо. «Теперь посади туда меня!» – сказал он. Киттёму сделал озабоченное лицо и спросил: «Тогда не могли бы вы разрешить жителям деревни отдыхать целую неделю?» Помещику не терпелось взлететь, поэтому он ответил: «Хорошо! Поторопись!»"}},{"t":[[["地主","じぬし"],["が","が"],["かご","かご"],["に","に"],["乗る","のる","乗る",5],["と","と"],["、"],["吉四六さん","きっちょむさん"],["は","は"],["友達","ともだち"],["に","に"],["ひも","ひも"],["を","を"],["引かせました","ひかせました","引く",16],["。"],["かご","かご"],["は","は"],["少し","すこし"],["だけ","だけ"],["上がりました","あがりました","上がる",2],["が","が"],["、"],["地主","じぬし"],["は","は"],["重","おも","重い"],["すぎました","すぎました","すぎる",2],["。"],["友達","ともだち"],["は","は"],["「"],["もう","もう"],["引けません","ひけません","引ける",6],["！"],["」"],["と","と"],["叫びました","さけびました","叫ぶ",2],["。"],["地主","じぬし"],["は","は"],["怖く","こわく","怖い"],["なって","なって","なる",3],["、"],["「"],["早く","はやく","早い"],["下ろしてくれ","おろしてくれ","下ろす",56],["！"],["」"],["と","と"],["泣きそうな","なきそうな","泣く",39],["声","こえ"],["で","で"],["言いました","いいました","言う",2],["。"]]],"tr":{"az":"Torpaq sahibi səbətə minəndə Kicçom dostuna kəndiri çəkdirdi. Səbət bir az qalxdı, amma torpaq sahibi çox ağır idi. Dostu «Artıq çəkə bilmirəm!» deyə qışqırdı. Torpaq sahibi qorxub ağlamağa yaxın bir səslə «Məni tez aşağı endirin!» dedi.","en":"When the landlord climbed into the basket, Kicchomu had his friend pull the rope. The basket rose only a little because the landlord was too heavy. His friend shouted, “I cannot pull anymore!” The frightened landlord almost cried as he shouted, “Get me down quickly!”","ru":"Когда помещик забрался в корзину, Киттёму велел другу тянуть верёвку. Корзина поднялась совсем немного, потому что помещик был слишком тяжёлым. Друг закричал: «Я больше не могу тянуть!» Испуганный помещик чуть не плакал и кричал: «Скорее опустите меня!»"}},{"t":[[["吉四六さん","きっちょむさん"],["は","は"],["地主","じぬし"],["を","を"],["安全","あんぜん"],["に","に","だ"],["下ろしました","おろしました","下ろす",2],["。"],["そして","そして"],["、"],["「"],["空","そら"],["を","を"],["飛ぶ","とぶ","飛ぶ",5],["より","より"],["、"],["みんな","みんな"],["を","を"],["笑わせる","わらわせる","笑う",100],["ほう","ほう"],["が","が"],["楽しい","たのしい"],["です","です"],["ね","ね"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["地主","じぬし"],["は","は"],["恥ずかしく","はずかしく","恥ずかしい"],["なりました","なりました","なる",2],["が","が"],["、"],["約束","やくそく"],["を","を"],["守りました","まもりました","守る",2],["。"],["村","むら"],["の","の"],["人たち","ひとたち"],["は","は"],["一週間","いっしゅうかん"],["ゆっくり","ゆっくり"],["休み","やすみ","休む",10],["、"],["吉四六さん","きっちょむさん"],["は","は"],["また","また"],["村中","むらじゅう"],["の","の"],["人","ひと"],["を","を"],["笑わせました","わらわせました","笑う",16],["。"]]],"tr":{"az":"Kicçom torpaq sahibini sağ-salamat aşağı endirdi. Sonra «Göydə uçmaqdansa, hamını güldürmək daha əyləncəlidir, elə deyilmi?» dedi. Torpaq sahibi utandı, amma sözünü tutdu. Kəndlilər bir həftə rahatca dincəldilər və Kicçom yenə bütün kəndi güldürdü.","en":"Kicchomu lowered the landlord safely. Then he said, “Making everyone laugh is more fun than flying in the sky, isn't it?” The landlord felt embarrassed but kept his promise. The villagers enjoyed a peaceful week of rest, and Kicchomu once again made the whole village laugh.","ru":"Киттёму благополучно опустил помещика на землю. Затем сказал: «Смешить людей гораздо веселее, чем летать по небу, правда?» Помещику стало стыдно, но он сдержал обещание. Жители деревни целую неделю спокойно отдыхали, а Киттёму снова рассмешил всю деревню."}}]},{"id":"l34b","ti":[[["小さな","ちいさな"],["侍","さむらい"],["と","と"],["月","つき"],["の","の"],["剣","けん"]]],"tt":{"az":"Balaca samuray və Ay qılıncı","en":"The Young Samurai and the Moon Sword","ru":"Юный самурай и лунный меч"},"P":[{"t":[[["むかしむかし","むかしむかし"],["、"],["山","やま"],["の","の"],["上","うえ"],["に","に"],["小さな","ちいさな"],["道場","どうじょう"],["が","が"],["ありました","ありました","ある",2],["。"],["そこ","そこ"],["に","に"],["は","は"],["、"],["ハル","ハル"],["と","と"],["いう","いう","いう",5],["若い","わかい"],["侍","さむらい"],["の","の"],["弟子","でし"],["が","が"],["住んでいました","すんでいました","住む",31],["。"],["ハル","ハル"],["の","の"],["先生","せんせい"],["は","は"],["とても","とても"],["厳しい","きびしい"],["人","ひと"],["でした","でした","です",9],["。"],["毎朝","まいあさ"],["、"],["先生","せんせい"],["は","は"],["ハル","ハル"],["を","を"],["走らせ","はしらせ","走る",100],["、"],["百回","ひゃくかい"],["も","も"],["木","き"],["の","の"],["剣","けん"],["を","を"],["振らせました","ふらせました","振る",16],["。"]]],"tr":{"az":"Biri var idi, biri yox idi, dağın başında kiçik bir qılınc məktəbi vardı. Orada Haru adlı gənc samuray şagirdi yaşayırdı. Harunun ustadı çox sərt insan idi. Hər səhər ustad Harunu qaçmağa və taxta qılıncı yüz dəfə yelləməyə məcbur edirdi.","en":"Long ago, there was a small sword-training school on a mountain. A young samurai apprentice named Haru lived there. Haru's master was very strict. Every morning, he made Haru run and swing a wooden sword one hundred times.","ru":"Давным-давно на вершине горы была маленькая школа фехтования. Там жил молодой ученик самурая по имени Хару. Его наставник был очень строгим. Каждое утро он заставлял Хару бегать и сто раз взмахивать деревянным мечом."}},{"t":[[["ある","ある","ある(連体詞)"],["夜","よる"],["、"],["ハル","ハル"],["は","は"],["森","もり"],["で","で"],["青く","あおく","青い"],["光る","ひかる","光る",5],["剣","けん"],["を","を"],["見つけました","みつけました","見つける",2],["。"],["剣","けん"],["に","に"],["は","は"],["小さな","ちいさな"],["月","つき"],["の","の"],["絵","え"],["が","が"],["ありました","ありました","ある",2],["。"],["ハル","ハル"],["が","が"],["剣","けん"],["に","に"],["触る","さわる","触る",5],["と","と"],["、"],["「"],["弱い","よわい"],["者","もの"],["を","を"],["守れ","まもれ","守る",10],["」"],["と","と"],["いう","いう","いう",5],["声","こえ"],["が","が"],["聞こえました","きこえました","聞こえる",2],["。"],["びっくり","びっくり"],["した","した","する",0],["ハル","ハル"],["は","は"],["、"],["すぐ","すぐ"],["先生","せんせい"],["に","に"],["見せ","みせ","見せる",10],["に","に"],["行きました","いきました","行く",2],["。"]]],"tr":{"az":"Bir gecə Haru meşədə mavi işıq saçan bir qılınc tapdı. Qılıncın üzərində balaca ay şəkli vardı. Haru qılınca toxunanda «Zəifləri qoru!» deyən bir səs eşitdi. Təəccüblənən Haru dərhal qılıncı ustadına göstərməyə getdi.","en":"One night, Haru found a sword glowing blue in the forest. A small moon was drawn on its blade. When Haru touched it, he heard a voice saying, “Protect the weak!” Surprised, Haru hurried to show it to his master.","ru":"Однажды ночью Хару нашёл в лесу меч, светящийся голубым светом. На клинке был изображён маленький месяц. Когда Хару прикоснулся к мечу, он услышал голос: «Защищай слабых!» Удивлённый Хару сразу побежал показать меч наставнику."}},{"t":[[["先生","せんせい"],["は","は"],["剣","けん"],["を","を"],["見て","みて","見る",3],["、"],["静かに","しずかに","静か",8],["言いました","いいました","言う",2],["。"],["「"],["その","その"],["剣","けん"],["を","を"],["使いたかったら","つかいたかったら","使う",106],["、"],["まず","まず"],["心","こころ"],["を","を"],["強く","つよく","強い"],["し","し","する",10],["なさい","なさい","なさる",10],["」"],["。"],["そして","そして"],["、"],["ハル","ハル"],["に","に"],["庭","にわ"],["の","の"],["掃除","そうじ"],["を","を"],["させました","させました","する",16],["。"],["ハル","ハル"],["は","は"],["「"],["少し","すこし"],["剣","けん"],["の","の"],["練習","れんしゅう"],["を","を"],["させていただけません","させていただけません","する",102],["か","か"],["」"],["と","と"],["頼みました","たのみました","頼む",2],["。"],["しかし","しかし"],["、"],["先生","せんせい"],["は","は"],["首","くび"],["を","を"],["横","よこ"],["に","に"],["振りました","ふりました","振る",2],["。"]]],"tr":{"az":"Ustad qılınca baxıb sakitcə dedi: «O qılıncdan istifadə etmək istəyirsənsə, əvvəlcə ruhunu gücləndir». Sonra Haruya həyəti təmizlətdirdi. Haru «Qılıncla bir az məşq etməyimə icazə verərsinizmi?» deyə xahiş etdi. Amma ustad başını yelləyərək razılaşmadı.","en":"The master looked at the sword and said quietly, “If you want to use that sword, first strengthen your heart.” Then he made Haru clean the courtyard. Haru asked, “Could you allow me to practice with the sword for a little while?” But the master shook his head.","ru":"Наставник посмотрел на меч и спокойно сказал: «Если хочешь пользоваться этим мечом, сначала укрепи свой дух». Затем он заставил Хару убирать двор. Хару попросил: «Не могли бы вы разрешить мне немного потренироваться с мечом?» Но наставник покачал головой."}},{"t":[[["次","つぎ"],["の","の"],["日","ひ"],["も","も"],["、"],["ハル","ハル"],["は","は"],["水","みず"],["を","を"],["運ば","はこば","運ぶ",10],["され","され","する",92],["、"],["長い","ながい"],["階段","かいだん"],["を","を"],["掃除","そうじ"],["させられました","させられました","する",107],["。"],["ハル","ハル"],["は","は"],["疲れて","つかれて","疲れる",3],["、"],["「"],["先生","せんせい"],["に","に"],["は","は"],["、"],["もっと","もっと"],["優しく","やさしく","優しい"],["教えてほしい","おしえてほしい","教える"],["」"],["と","と"],["思いました","おもいました","思う",2],["。"],["その","その"],["とき","とき"],["、"],["小さな","ちいさな"],["狐","きつね"],["が","が"],["庭","にわ"],["に","に"],["入ってきました","はいってきました","入る",23],["。"],["狐","きつね"],["は","は"],["足","あし"],["を","を"],["けがして","けがして","けがす",3],["、"],["悲し","かなし","悲しい"],["そうに","そうに","そう",8],["鳴いていました","ないていました","鳴く",15],["。"]]],"tr":{"az":"Ertəsi gün də Haruya su daşıtdılar və uzun pilləkəni təmizlətdilər. Haru yorulub «Kaş ustad mənə daha mehriban dərs keçəydi» deyə düşündü. Elə bu vaxt həyətə balaca bir tülkü girdi. Tülkünün ayağı yaralanmışdı və o, kədərli səslə zingildəyirdi.","en":"The next day, Haru was made to carry water and clean a long staircase. Exhausted, he thought, “I wish my master would teach me more kindly.” Just then, a small fox entered the courtyard. Its leg was injured, and it cried sadly.","ru":"На следующий день Хару снова заставили носить воду и убирать длинную лестницу. Устав, он подумал: «Хочу, чтобы учитель был со мной добрее». В этот момент во двор забежала маленькая лиса. У неё была ранена лапа, и она жалобно скулила."}},{"t":[[["ハル","ハル"],["は","は"],["先生","せんせい"],["に","に"],["「"],["狐","きつね"],["を","を"],["助け","たすけ","助ける",10],["に","に"],["行かせていただけません","いかせていただけません","行く",102],["か","か"],["」"],["と","と"],["聞きました","ききました","聞く",2],["。"],["先生","せんせい"],["は","は"],["「"],["行け","いけ","行く",10],["。"],["でも","でも"],["、"],["気","き"],["を","を"],["つけろ","つけろ","つける",10],["」"],["と","と"],["答えました","こたえました","答える",2],["。"],["ハル","ハル"],["は","は"],["狐","きつね"],["を","を"],["抱いて","いだいて","抱く",3],["、"],["山","やま"],["の","の"],["小さな","ちいさな"],["小屋","こや"],["へ","へ"],["運びました","はこびました","運ぶ",2],["。"],["そこ","そこ"],["で","で"],["、"],["薬","くすり"],["を","を"],["作る","つくる","作る",5],["おばあさん","おばあさん"],["に","に"],["「"],["この","この"],["子","こ"],["を","を"],["治していただけません","なおしていただけません","治す",6],["か","か"],["」"],["と","と"],["頼みました","たのみました","頼む",2],["。"]]],"tr":{"az":"Haru ustadından «Tülküyə kömək etməyə getməyimə icazə verərsinizmi?» deyə soruşdu. Ustad «Get. Amma ehtiyatlı ol!» cavabını verdi. Haru tülkünü qucağına alıb dağdakı balaca daxmaya apardı. Orada dərman hazırlayan yaşlı qadından «Bu balacanı sağalda bilərsinizmi?» deyə xahiş etdi.","en":"Haru asked his master, “Could you allow me to go and help the fox?” The master replied, “Go. But be careful.” Haru carried the fox to a small hut on the mountain. There, he asked an old woman who made medicines, “Could you please heal this little one?”","ru":"Хару спросил наставника: «Не могли бы вы разрешить мне пойти помочь лисе?» Наставник ответил: «Иди. Но будь осторожен». Хару взял лису на руки и отнёс в маленькую хижину на горе. Там он попросил старушку, которая готовила лекарства: «Не могли бы вы вылечить эту малышку?»"}},{"t":[[["その","その"],["夜","よる"],["、"],["山","やま"],["に","に"],["黒い","くろい"],["雲","くも"],["が","が"],["集まり","あつまり","集まる",10],["、"],["大きな","おおきな"],["風","かぜ"],["が","が"],["吹きました","ふきました","吹く",2],["。"],["森","もり"],["から","から"],["恐ろしい","おそろしい"],["声","こえ"],["が","が"],["聞こえ","きこえ","聞こえる",10],["、"],["村","むら"],["の","の"],["子どもたち","こどもたち"],["は","は"],["泣き","なき","泣く",10],["始めました","はじめました","始める",2],["。"],["先生","せんせい"],["は","は"],["ハル","ハル"],["に","に"],["「"],["村","むら"],["へ","へ"],["行って","いって","行く",3],["、"],["子どもたち","こどもたち"],["を","を"],["守り","まもり","守る",10],["なさい","なさい","なさる",10],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["ハル","ハル"],["は","は"],["月","つき"],["の","の"],["剣","けん"],["を","を"],["持って","もって","持つ",3],["、"],["暗い","くらい"],["道","みち"],["を","を"],["走りました","はしりました","走る",2],["。"]]],"tr":{"az":"Həmin gecə dağın üzərində qara buludlar toplandı və güclü külək əsdi. Meşədən qorxunc bir səs gəldi, kənd uşaqları ağlamağa başladı. Ustad Haruya «Kəndə get və uşaqları qoru!» dedi. Haru Ay qılıncını götürüb qaranlıq yolla qaçdı.","en":"That night, black clouds gathered over the mountain, and a strong wind began to blow. A frightening sound came from the forest, and the village children started crying. The master told Haru, “Go to the village and protect the children.” Haru took the Moon Sword and ran down the dark path.","ru":"Той ночью над горой собрались чёрные тучи и подул сильный ветер. Из леса раздался страшный голос, и деревенские дети заплакали. Наставник сказал Хару: «Иди в деревню и защити детей». Хару взял лунный меч и побежал по тёмной дороге."}},{"t":[[["村","むら"],["の","の"],["前","まえ"],["に","に"],["は","は"],["、"],["大きな","おおきな"],["黒い","くろい"],["影","かげ"],["が","が"],["立っていました","たっていました","立つ",15],["。"],["ハル","ハル"],["は","は"],["「"],["ここ","ここ"],["から","から"],["出ていけ","でていけ","出る",81],["！"],["」"],["と","と"],["叫びました","さけびました","叫ぶ",2],["。"],["でも","でも"],["、"],["影","かげ"],["は","は"],["動きませんでした","うごきませんでした","動く",4],["。"],["その","その"],["とき","とき"],["、"],["昼間","ひるま"],["助けた","たすけた","助ける",0],["狐","きつね"],["が","が"],["現れ","あらわれ","現れる",10],["、"],["月","つき"],["の","の"],["剣","けん"],["を","を"],["光らせました","ひからせました","光る",16],["。"],["明るい","あかるい"],["光","ひかり"],["の","の"],["中","なか"],["で","で"],["、"],["黒い","くろい"],["影","かげ"],["は","は"],["小さな","ちいさな"],["雲","くも"],["に","に"],["なって","なって","なる",3],["消えました","きえました","消える",2],["。"]]],"tr":{"az":"Kəndin qarşısında nəhəng qara bir kölgə dayanmışdı. Haru «Buradan rədd ol!» deyə qışqırdı. Amma kölgə yerindən tərpənmədi. Elə bu vaxt gündüz xilas etdiyi tülkü peyda oldu və Ay qılıncını işıqlandırdı. Parlaq işığın içində qara kölgə kiçik buluda çevrilib yox oldu.","en":"A huge black shadow stood in front of the village. Haru shouted, “Get out of here!” But the shadow did not move. Just then, the fox he had saved appeared and made the Moon Sword shine. In the bright light, the black shadow turned into a tiny cloud and vanished.","ru":"Перед деревней стояла огромная чёрная тень. Хару закричал: «Убирайся отсюда!» Но тень не двигалась. В этот момент появилась лиса, которую он спас днём, и заставила лунный меч засиять. В ярком свете чёрная тень превратилась в маленькое облачко и исчезла."}},{"t":[[["翌朝","よくあさ"],["、"],["先生","せんせい"],["は","は"],["ハル","ハル"],["を","を"],["道場","どうじょう"],["に","に"],["呼びました","よびました","呼ぶ",2],["。"],["「"],["よく","よく"],["やった","やった","やる",0],["。"],["お前","おまえ"],["は","は"],["本当","ほんとう"],["の","の"],["侍","さむらい"],["だ","だ","です"],["」"],["と","と"],["ほめました","ほめました","ほめる",2],["。"],["ハル","ハル"],["は","は"],["笑って","わらって","笑う",3],["、"],["「"],["で","で"],["は","は"],["、"],["今日","きょう"],["は","は"],["休ませていただけません","やすませていただけません","休む",102],["か","か"],["」"],["と","と"],["聞きました","ききました","聞く",2],["。"],["先生","せんせい"],["は","は"],["初めて","はじめて"],["大きく","おおきく","大きい"],["笑い","わらい","笑う",10],["、"],["「"],["よし","よし"],["、"],["今日","きょう"],["は","は"],["狐","きつね"],["と","と"],["遊び","あそび","遊ぶ",10],["なさい","なさい","なさる",10],["！"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["狐","きつね"],["は","は"],["うれし","うれし","うれしい"],["そうに","そうに","そう",8],["、"],["ハル","ハル"],["の","の"],["肩","かた"],["に","に"],["飛び乗りました","とびのりました","飛び乗る",2],["。"]]],"tr":{"az":"Ertəsi səhər ustad Harunu məşq zalına çağırdı. «Əla iş gördün. Sən əsl samuraysan!» deyə onu təriflədi. Haru gülümsəyib «Onda bu gün istirahət etməyimə icazə verərsinizmi?» deyə soruşdu. Ustad ilk dəfə ürəkdən güldü və «Yaxşı, bu gün tülkü ilə oyna!» dedi. Tülkü sevinclə Harunun çiyninə tullandı.","en":"The next morning, the master called Haru to the training hall. “Well done. You are a true samurai,” he praised him. Haru smiled and asked, “Then could you allow me to rest today?” For the first time, the master laughed heartily and said, “All right, play with the fox today!” The happy fox jumped onto Haru's shoulder.","ru":"На следующее утро наставник позвал Хару в тренировочный зал. «Молодец. Ты настоящий самурай», – похвалил он его. Хару улыбнулся и спросил: «Тогда не могли бы вы разрешить мне сегодня отдохнуть?» Наставник впервые громко рассмеялся и сказал: «Хорошо, сегодня играй с лисой!» Довольная лиса прыгнула Хару на плечо."}}]},{"id":"l34c","ti":[[["早く","はやく","早い"],["帰りたい","かえりたい","帰る",30],["お父さん","おとうさん"]]],"tt":{"az":"Evə tez qayıtmaq istəyən ata","en":"The Father Who Wanted to Go Home Early","ru":"Папа, который хотел пораньше домой"},"P":[{"t":[[["ある","ある","ある(連体詞)"],["町","まち"],["に","に"],["、"],["タケシさん","タケシさん"],["と","と"],["いう","いう","いう",5],["会社員","かいしゃいん"],["が","が"],["住んでいました","すんでいました","住む",31],["。"],["タケシさん","タケシさん"],["に","に"],["は","は"],["、"],["七歳","ななさい"],["の","の"],["娘","むすめ"],["の","の"],["ミオ","ミオ"],["が","が"],["いました","いました","いる",2],["。"],["ミオ","ミオ"],["は","は"],["毎日","まいにち"],["、"],["父親","ちちおや"],["と","と"],["遊びたがりました","あそびたがりました","遊ぶ",2],["。"],["でも","でも"],["、"],["タケシさん","タケシさん"],["の","の"],["課長","かちょう"],["は","は"],["仕事","しごと"],["が","が"],["大好き","だいすき"],["で","で","だ"],["、"],["みんな","みんな"],["を","を"],["遅く","おそく"],["まで","まで"],["働かせました","はたらかせました","働く",16],["。"]]],"tr":{"az":"Bir şəhərdə Takeşi adlı ofis işçisi yaşayırdı. Onun Mio adlı yeddi yaşlı qızı vardı. Mio hər gün atası ilə oynamaq istəyirdi. Amma Takeşinin şöbə müdiri işləməyi çox sevirdi və hamını gec saatlara qədər işlədirdi.","en":"In a town lived an office worker named Takeshi. He had a seven-year-old daughter named Mio. Every day, Mio wanted to play with her father. But Takeshi's section manager loved working and made everyone stay late.","ru":"В одном городе жил офисный работник по имени Такэси. У него была семилетняя дочь Мио. Каждый день Мио хотела играть с папой. Но начальник отдела Такэси очень любил работу и заставлял всех задерживаться допоздна."}},{"t":[[["ある","ある","ある(連体詞)"],["金曜","きんよう"],["日","ひ"],["、"],["ミオ","ミオ"],["の","の"],["学校","がっこう"],["で","で"],["小さな","ちいさな"],["発表","はっぴょう"],["会","かい"],["が","が"],["ありました","ありました","ある",2],["。"],["ミオ","ミオ"],["は","は"],["朝","あさ"],["、"],["「"],["今日","きょう"],["は","は"],["絶対","ぜったい"],["に","に"],["来て","きて","来る",3],["ね","ね"],["。"],["私","わたし"],["の","の"],["歌","うた"],["を","を"],["聞いてほしい","きいてほしい","聞く"],["の","の"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["タケシさん","タケシさん"],["は","は"],["「"],["わかった","わかった","わかる",0],["。"],["必ず","かならず"],["行く","いく","行く",5],["よ","よ"],["」"],["と","と"],["約束","やくそく"],["しました","しました","する",2],["。"],["そして","そして"],["、"],["会社","かいしゃ"],["へ","へ"],["急いで行きました","いそいでいきました","急ぐ",2],["。"]]],"tr":{"az":"Bir cümə günü Mionun məktəbində kiçik bir çıxış tədbiri vardı. Mio səhər «Bu gün mütləq gəl, yaxşı? İstəyirəm mahnımı dinləyəsən» dedi. Takeşi «Oldu, mütləq gələcəyəm» deyə söz verdi. Sonra tələsik işə getdi.","en":"One Friday, Mio's school was holding a small performance. That morning, Mio said, “You absolutely must come today. I want you to hear my song.” Takeshi promised, “All right. I'll definitely be there.” Then he hurried to the office.","ru":"В одну пятницу в школе Мио должен был состояться небольшой концерт. Утром Мио сказала: «Обязательно приходи сегодня. Я хочу, чтобы ты послушал мою песню». Такэси пообещал: «Хорошо, я обязательно приду». Затем он поспешил на работу."}},{"t":[[["昼休み","ひるやすみ"],["、"],["タケシさん","タケシさん"],["は","は"],["課長","かちょう"],["の","の"],["部屋","へや"],["へ","へ"],["行きました","いきました","行く",2],["。"],["「"],["娘","むすめ"],["の","の"],["発表","はっぴょう"],["会","かい"],["が","が"],["ある","ある","ある",5],["の","の"],["で","で","だ"],["、"],["今日","きょう"],["は","は"],["三","さん"],["時","じ"],["に","に"],["帰らせていただけません","かえらせていただけません","帰る",102],["か","か"],["」"],["と","と"],["頼みました","たのみました","頼む",2],["。"],["ところ","ところ"],["が","が"],["、"],["課長","かちょう"],["は","は"],["「"],["まだ","まだ"],["仕事","しごと"],["が","が"],["ある","ある","ある(連体詞)"],["。"],["先","さき"],["に","に"],["この","この"],["書類","しょるい"],["を","を"],["終わらせ","おわらせ","終わる",100],["なさい","なさい","なさる",10],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["タケシさん","タケシさん"],["は","は"],["困りました","こまりました","困る",2],["が","が"],["、"],["急いで","いそいで","急ぐ",13],["仕事","しごと"],["を","を"],["始めました","はじめました","始める",2],["。"]]],"tr":{"az":"Nahar fasiləsində Takeşi müdirin otağına getdi. «Qızımın məktəbdə çıxışı var. Bu gün saat üçdə getməyimə icazə verərsinizmi?» deyə xahiş etdi. Amma müdir «Hələ iş var. Əvvəlcə bu sənədləri bitir!» dedi. Takeşi çətin vəziyyətdə qalsa da, tələsik işə başladı.","en":"During lunch, Takeshi went to the manager's office. He asked, “My daughter has a school performance. Could you allow me to leave at three today?” However, the manager said, “There is still work to do. Finish these documents first.” Takeshi was troubled, but he quickly started working.","ru":"Во время обеденного перерыва Такэси пошёл в кабинет начальника. Он попросил: «У моей дочери школьный концерт. Не могли бы вы разрешить мне сегодня уйти в три часа?» Но начальник сказал: «Работа ещё есть. Сначала закончи эти документы». Такэси расстроился, но поспешил приступить к работе."}},{"t":[[["隣","となり"],["の","の"],["席","せき"],["の","の"],["先輩","せんぱい"],["は","は"],["、"],["タケシさん","タケシさん"],["の","の"],["顔","かお"],["を","を"],["見て","みて","見る",3],["心配","しんぱい"],["しました","しました","する",2],["。"],["タケシさん","タケシさん"],["は","は"],["「"],["この","この"],["数字","すうじ"],["を","を"],["確認","かくにん"],["してもらえません","してもらえません","する",6],["か","か"],["」"],["と","と"],["頼みました","たのみました","頼む",2],["。"],["先輩","せんぱい"],["は","は"],["「"],["もちろん","もちろん"],["。"],["子ども","こども"],["を","を"],["待たせて","またせて","待つ",17],["は","は"],["いけない","いけない","いける",19],["よ","よ"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["二人","ふたり"],["は","は"],["力","ちから"],["を","を"],["合わせて","あわせて","合わせる",3],["、"],["三","さん"],["時","じ"],["前","まえ"],["に","に"],["書類","しょるい"],["を","を"],["全部","ぜんぶ"],["終わらせました","おわらせました","終わる",16],["。"]]],"tr":{"az":"Yan masada oturan təcrübəli həmkarı Takeşinin üzünü görüb narahat oldu. Takeşi «Bu rəqəmləri yoxlaya bilərsinizmi?» deyə xahiş etdi. Həmkarı «Əlbəttə. Uşağı gözlətmək olmaz» dedi. İkisi birlikdə çalışıb bütün sənədləri saat üçdən əvvəl bitirdilər.","en":"The senior coworker at the next desk noticed Takeshi's worried face. Takeshi asked, “Could you check these numbers for me?” His coworker said, “Of course. You mustn't keep a child waiting.” Working together, they finished all the documents before three.","ru":"Опытный коллега за соседним столом заметил обеспокоенное лицо Такэси. Такэси попросил: «Не могли бы вы проверить эти цифры?» Коллега ответил: «Конечно. Нельзя заставлять ребёнка ждать». Вместе они закончили все документы до трёх часов."}},{"t":[[["タケシさん","タケシさん"],["は","は"],["もう","もう"],["一度","いちど"],["、"],["課長","かちょう"],["に","に"],["「"],["帰らせていただけません","かえらせていただけません","帰る",102],["か","か"],["」"],["と","と"],["聞きました","ききました","聞く",2],["。"],["課長","かちょう"],["は","は"],["書類","しょるい"],["を","を"],["見て","みて","見る",3],["、"],["少し","すこし"],["驚きました","おどろきました","驚く",2],["。"],["「"],["もう","もう"],["終わった","おわった","終わる",0],["の","の"],["か","か"],["。"],["よし","よし"],["、"],["帰れ","かえれ","帰る",10],["！"],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["タケシさん","タケシさん"],["は","は"],["何","なん"],["度","ど"],["も","も"],["お礼","おれい"],["を","を"],["言って","いって","言う",3],["、"],["会社","かいしゃ"],["を","を"],["飛び出しました","とびだしました","飛び出す",2],["。"]]],"tr":{"az":"Takeşi yenidən müdirindən «Getməyimə icazə verərsinizmi?» deyə soruşdu. Müdir sənədlərə baxıb bir az təəccübləndi. «Artıq bitirmisən? Yaxşı, get!» dedi. Takeşi dəfələrlə təşəkkür edib ofisdən tələsik çıxdı.","en":"Takeshi asked the manager once more, “Could you please allow me to leave?” The manager looked at the documents in surprise. “You've finished already? All right, go!” he said. Takeshi thanked him repeatedly and rushed out of the office.","ru":"Такэси ещё раз спросил начальника: «Не могли бы вы разрешить мне уйти?» Начальник посмотрел на документы и немного удивился. «Уже закончил? Ладно, иди!» – сказал он. Такэси несколько раз поблагодарил его и выбежал из офиса."}},{"t":[[["学校","がっこう"],["に","に"],["着く","つく","着く",5],["と","と"],["、"],["発表","はっぴょう"],["会","かい"],["は","は"],["もう","もう"],["始まっていました","はじまっていました","始まる",15],["。"],["タケシさん","タケシさん"],["は","は"],["先生","せんせい"],["に","に"],["「"],["後ろ","うしろ"],["から","から"],["入れていただけません","いれていただけません","入れる",6],["か","か"],["」"],["と","と"],["小さな","ちいさな"],["声","こえ"],["で","で"],["頼みました","たのみました","頼む",2],["。"],["先生","せんせい"],["は","は"],["笑って","わらって","笑う",3],["、"],["静かに","しずかに","静か",8],["ドア","ドア"],["を","を"],["開けてくれました","あけてくれました","開ける",54],["。"],["ミオ","ミオ"],["は","は"],["舞台","ぶたい"],["の","の"],["上","うえ"],["から","から"],["父親","ちちおや"],["を","を"],["見つけ","みつけ","見つける",10],["、"],["うれし","うれし","うれしい"],["そうに","そうに","そう",8],["歌いました","うたいました","歌う",2],["。"]]],"tr":{"az":"Takeşi məktəbə çatanda çıxış artıq başlamışdı. O, müəllimdən alçaq səslə «Arxa tərəfdən içəri girməyimə icazə verərsinizmi?» deyə xahiş etdi. Müəllim gülümsəyib qapını sakitcə açdı. Mio səhnədən atasını görüb sevinclə oxumağa başladı.","en":"When Takeshi reached the school, the performance had already begun. He quietly asked a teacher, “Could you let me enter from the back?” The teacher smiled and silently opened the door. Mio spotted her father from the stage and sang happily.","ru":"Когда Такэси добрался до школы, концерт уже начался. Он тихо попросил учительницу: «Не могли бы вы разрешить мне войти сзади?» Учительница улыбнулась и тихонько открыла дверь. Мио увидела папу со сцены и радостно запела."}},{"t":[[["ところ","ところ"],["が","が"],["、"],["ミオ","ミオ"],["の","の"],["歌","うた"],["が","が"],["終わる","おわる","終わる",5],["と","と"],["、"],["先生","せんせい"],["は","は"],["客席","きゃくせき"],["に","に"],["向かって","むかって","向かう",3],["言いました","いいました","言う",2],["。"],["「"],["次","つぎ"],["は","は"],["、"],["お父さんたち","おとうさんたち"],["に","に"],["も","も"],["歌ってもらいます","うたってもらいます","歌う",108],["！"],["」"],["。"],["タケシさん","タケシさん"],["は","は"],["びっくり","びっくり"],["して","して","する",3],["、"],["隣","となり"],["の","の"],["人","ひと"],["に","に"],["「"],["本当","ほんとう"],["です","です"],["か","か"],["」"],["と","と"],["聞きました","ききました","聞く",2],["。"],["先生","せんせい"],["に","に"],["前","まえ"],["へ","へ"],["出させられた","ださせられた","出す",109],["お父さんたち","おとうさんたち"],["は","は"],["、"],["みんな","みんな"],["顔","かお"],["を","を"],["赤く","あかく","赤い"],["していました","していました","する",15],["。"]]],"tr":{"az":"Amma Mionun mahnısı bitəndə müəllim tamaşaçılara dedi: «İndi isə atalarımızdan da mahnı oxumalarını xahiş edirik!» Takeşi təəccüblənib yanındakı adamdan «Doğrudan?» deyə soruşdu. Müəllimin qabağa çıxartdığı ataların hamısının üzü qızarmışdı.","en":"But when Mio's song ended, the teacher announced to the audience, “Next, we're going to have the fathers sing too!” Takeshi was shocked and asked the person beside him, “Really?” The fathers whom the teacher had made come to the front were all blushing.","ru":"Но когда песня Мио закончилась, учительница объявила зрителям: «А теперь попросим пап тоже спеть!» Такэси удивился и спросил соседа: «Правда?» Все папы, которых учительница вызвала вперёд, покраснели от смущения."}},{"t":[[["タケシさん","タケシさん"],["も","も"],["舞台","ぶたい"],["に","に"],["立たされ","たたされ","立たす",92],["、"],["子どもたち","こどもたち"],["の","の"],["前","まえ"],["で","で"],["歌わされました","うたわされました","歌わす",27],["。"],["歌","うた"],["は","は"],["あまり","あまり"],["上手","じょうず"],["で","で","だ"],["は","は"],["ありませんでした","ありませんでした","ある",4],["が","が"],["、"],["ミオ","ミオ"],["は","は"],["大笑い","おおわらい"],["しました","しました","する",2],["。"],["その","その"],["とき","とき"],["、"],["客席","きゃくせき"],["の","の"],["後ろ","うしろ"],["から","から"],["大きな","おおきな"],["拍手","はくしゅ"],["が","が"],["聞こえました","きこえました","聞こえる",2],["。"],["なん","なん"],["と","と"],["、"],["そこ","そこ"],["に","に"],["は","は"],["会社","かいしゃ"],["の","の"],["課長","かちょう"],["が","が"],["いて","いて","いる",3],["、"],["うれし","うれし","うれしい"],["そうに","そうに","そう",8],["手","て"],["を","を"],["たたいていました","たたいていました","たたく",15],["。"]]],"tr":{"az":"Takeşini də səhnəyə çıxmağa və uşaqların qarşısında oxumağa məcbur etdilər. O, elə də yaxşı oxumurdu, amma Mio ürəkdən güldü. Elə bu vaxt zalın arxasından güclü alqış səsi gəldi. Nə görsələr yaxşıdır? Orada Takeşinin müdiri dayanıb sevinclə əl çalırdı!","en":"Takeshi was also made to stand on stage and sing in front of the children. He was not a very good singer, but Mio laughed with delight. Suddenly, loud applause came from the back of the hall. To everyone's surprise, Takeshi's manager was standing there, clapping happily!","ru":"Такэси тоже заставили выйти на сцену и петь перед детьми. Пел он не очень хорошо, зато Мио от души смеялась. Вдруг из задней части зала раздались громкие аплодисменты. Каково же было удивление Такэси, когда он увидел там своего начальника, который радостно хлопал в ладоши!"}},{"t":[[["実","じつ"],["は","は"],["、"],["課長","かちょう"],["の","の"],["孫","まご"],["も","も"],["同じ","おなじ"],["学校","がっこう"],["に","に"],["通っていました","かよっていました","通う",15],["。"],["課長","かちょう"],["は","は"],["「"],["君","きみ"],["の","の"],["歌","うた"],["は","は"],["おもしろかった","おもしろかった","おもしろい",0],["。"],["明日","あした"],["から","から"],["は","は"],["、"],["みんな","みんな"],["を","を"],["早く","はやく","早い"],["帰らせよう","かえらせよう","帰る",100],["」"],["と","と"],["言いました","いいました","言う",2],["。"],["タケシさん","タケシさん"],["は","は"],["ほっと","ほっと"],["して","して","する",3],["、"],["ミオ","ミオ"],["の","の"],["手","て"],["を","を"],["握りました","にぎりました","握る",2],["。"],["帰り道","かえりみち"],["、"],["ミオ","ミオ"],["は","は"],["「"],["明日","あした"],["も","も"],["歌って","うたって","歌う",3],["ね","ね"],["」"],["と","と"],["言いました","いいました","言う",2],["が","が"],["、"],["タケシさん","タケシさん"],["は","は"],["笑って","わらって","笑う",3],["「"],["それ","それ"],["だけ","だけ"],["は","は"],["勘弁","かんべん"],["して","して","する",3],["！"],["」"],["と","と"],["答えました","こたえました","答える",2],["。"]]],"tr":{"az":"Məlum oldu ki, müdirin nəvəsi də həmin məktəbdə oxuyurdu. Müdir «Mahnın çox gülməli idi. Sabahdan hamının evə tez getməsinə icazə verəcəyəm» dedi. Takeşi rahat nəfəs alıb Mionun əlindən tutdu. Evə gedərkən Mio «Sabah da oxu, ata!» dedi, amma Takeşi gülərək «Bir bu olmasın!» cavabını verdi.","en":"As it turned out, the manager's grandchild attended the same school. The manager said, “Your singing was funny. From tomorrow, I'll let everyone go home early.” Takeshi felt relieved and held Mio's hand. On the way home, Mio said, “Sing again tomorrow!” But Takeshi laughed and replied, “Anything but that!”","ru":"Оказалось, что в той же школе учился и внук начальника. Начальник сказал: «Ты очень забавно пел. С завтрашнего дня я буду отпускать всех домой пораньше». Такэси вздохнул с облегчением и взял Мио за руку. По дороге домой Мио сказала: «Папа, спой и завтра!» Но Такэси рассмеялся и ответил: «Только не это!»"}}]}],"G":{"あまり":{"b":"あまり","p":"ad","m":{"az":"o qədər də, çox da","en":"not very, not much","ru":"не очень, не особо"},"n":{"az":"Adətən inkarla işlənir: あまり寒くない = o qədər də soyuq deyil.","en":"Usually used with a negative: あまり寒くない = not very cold.","ru":"Обычно используется с отрицанием: あまり寒くない = не очень холодно."}},"ある":{"b":"ある","p":"v","m":{"az":"olmaq, var olmaq (cansız şeylər)","en":"to be, to exist (things)","ru":"быть, иметься (о предметах)"},"n":{"az":"Cansız şeylər üçün: 電池がありました = batareya var idi. Canlılar üçün いる. 書いてありました = yazılmışdı (yazılı vəziyyətdə idi).","en":"For non-living things: 電池がありました = there was a battery. For living things use いる. 書いてありました = was written (and stayed so).","ru":"Для неодушевлённых: 電池がありました = была батарейка. Для живых – いる. 書いてありました = было написано."}},"ある(連体詞)":{"b":"ある","p":"dm","m":{"az":"bir, hansısa (bir)","en":"a certain, one","ru":"некий, один"},"n":{"az":"ある朝 = bir səhər; ある日 = bir gün. İsimdən əvvəl gələndə 'var olmaq' feili deyil.","en":"ある朝 = one morning. Before a noun it is not the verb 'to exist'.","ru":"ある朝 = однажды утром. Перед существительным это не глагол 'быть'."}},"ある日":{"b":"ある日 (あるひ)","p":"ex","m":{"az":"bir gün","en":"one day","ru":"однажды"}},"いい":{"b":"いい・良い (よい)","p":"ai","m":{"az":"yaxşı","en":"good","ru":"хороший"},"n":{"az":"İ-sifətdir, lakin dəyişən formaları よい əsasından yaranır: よくない, よかった.","en":"An i-adjective whose inflected forms use よい: よくない, よかった.","ru":"И-прилагательное, изменяемые формы которого образуются от よい: よくない, よかった."}},"いう":{"b":"という","p":"ex","m":{"az":"adlı, deyilən","en":"called, named","ru":"под названием"},"n":{"az":"N という名前 = N adlı ad: 「かぐや」という名前 = «Kaquya» adı.","en":"N という名前 = the name \"N\".","ru":"N という名前 = имя «N»."}},"いける":{"b":"行ける (いける)","p":"v","m":{"az":"gedə bilmək","en":"to be able to go","ru":"мочь пойти"},"n":{"az":"いけません qadağa ifadəsində olmaz deməkdir və bu halda 行ける potensial felindən fərqlidir.","en":"いけません can mean must not in prohibitions and is then distinct from the potential verb 行ける.","ru":"いけません в запретах означает нельзя и отличается от потенциального глагола 行ける."}},"いじ":{"b":"意地 (いじ)","p":"n","m":{"az":"inad, tərslik, qürur","en":"stubbornness, pride","ru":"упрямство, самолюбие"},"n":{"az":"意地を張る inad etmək, 意地悪 isə qəsdən pislik edən və ya qəddar deməkdir.","en":"意地を張る means to be stubborn; 意地悪 means mean or spiteful.","ru":"意地を張る означает упрямиться; 意地悪 - злой или вредный."}},"いつ":{"b":"いつ","p":"pr","m":{"az":"nə vaxt","en":"when","ru":"когда"},"n":{"az":"Adətən に qəbul etmir: いつ行きますか.","en":"Usually takes no に: いつ行きますか.","ru":"Обычно употребляется без に: いつ行きますか."}},"いる":{"b":"いる","p":"v","m":{"az":"olmaq, var olmaq (canlılar); yaşamaq","en":"to be, exist (living things)","ru":"быть, находиться (о живых)"},"n":{"az":"Canlılar üçün: 女の子がいました = bir qız var idi. 〜ている = davam edən hal.","en":"For living things: 女の子がいました = there was a girl. 〜ている = continuous.","ru":"Для живых: 女の子がいました = была девочка. 〜ている – длительный вид."}},"うれしい":{"b":"嬉しい (うれしい)","p":"ai","m":{"az":"sevincli, şad","en":"happy, glad","ru":"радостный, довольный"},"n":{"az":"い sifətidir, うれし bağlayıcı və ya başqa forma yaratmaq üçün əsasdır.","en":"An i-adjective, with うれし as the stem used to form other expressions.","ru":"Прилагательное на い, うれし - основа для образования других форм."}},"おばあさん":{"b":"おばあさん","p":"n","m":{"az":"nənə; qarı","en":"grandmother; old woman","ru":"бабушка; старушка"}},"おもしろい":{"b":"おもしろい","p":"ai","m":{"az":"maraqlı, əyləncəli","en":"interesting, amusing","ru":"интересный, забавный"},"n":{"az":"い-sifətdir və həm maraqlı, həm də gülməli mənasında işlənə bilər.","en":"An i-adjective that can mean either interesting or amusing.","ru":"Прилагательное на い, которое может означать интересный или забавный."}},"お前":{"b":"お前 (おまえ)","p":"pr","m":{"az":"sən","en":"you","ru":"ты"},"n":{"az":"Çox qeyri-rəsmi müraciətdir; yaxınlar arasında işlənə bilər, amma kobud səslənə bilər.","en":"A very informal form of you; it can sound rough or rude outside close relationships.","ru":"Очень неформальное ты; вне близкого общения может звучать грубо."}},"お父さん":{"b":"お父さん (おとうさん)","p":"n","m":{"az":"ata","en":"father; dad","ru":"папа; отец"},"n":{"az":"Ataya müraciətdə və başqasının atası haqqında işlənir; kənar şəxslərə öz atandan danışarkən adətən 父 deyilir.","en":"Used to address your father or refer to someone else's; use 父 for your own father when speaking to outsiders.","ru":"Используется при обращении к папе или о чужом отце; о своём отце посторонним обычно говорят 父."}},"お父さんたち":{"b":"お父さんたち (おとうさんたち)","p":"n","m":{"az":"atalar, atalar və yanındakılar","en":"fathers, father and the others","ru":"отцы, папа и остальные"},"n":{"az":"たち burada bir neçə atanı və ya ata ilə birlikdə olan qrupu bildirə bilər.","en":"たち can mean several fathers or a group including one's father.","ru":"たち может обозначать нескольких отцов или группу вместе с папой."}},"お礼":{"b":"お礼 (おれい)","p":"n","m":{"az":"təşəkkür; minnətdarlıq","en":"thanks; gratitude","ru":"благодарность"},"n":{"az":"お礼を言う təşəkkür etmək, お礼に isə minnətdarlıq əlaməti olaraq deməkdir.","en":"お礼を言う means to express thanks; お礼に means as a token of gratitude.","ru":"お礼を言う означает поблагодарить, а お礼に в знак благодарности."}},"か":{"b":"か","p":"pt","m":{"az":"sual hissəciyi","en":"question particle","ru":"вопросительная частица"},"n":{"az":"Cümlənin sonuna gəlir və onu suala çevirir: 学生ですか = Tələbəsən? Yaponcada sual işarəsi əvəzinə adətən 。 yazılır.","en":"Goes at the end and turns the sentence into a question: 学生ですか = Are you a student? Japanese usually writes 。 instead of ?.","ru":"Ставится в конце и делает предложение вопросом: 学生ですか = Вы студент? Обычно пишут 。, а не ?."}},"かご":{"b":"籠 (かご)","p":"n","m":{"az":"səbət","en":"basket","ru":"корзина"}},"から":{"b":"から","p":"pt","m":{"az":"-dan, -dən (haradan)","en":"from","ru":"из, от"},"n":{"az":"Başlanğıc nöqtəsini göstərir: 月から来ました = Aydan gəldim.","en":"Marks the starting point: 月から来ました = I came from the Moon.","ru":"Указывает исходную точку: 月から来ました = Я прилетела с Луны."}},"が":{"b":"が","p":"pt","m":{"az":"subyekt hissəciyi","en":"subject marker","ru":"частица подлежащего"},"n":{"az":"Hərəkəti edən və ya mövcud olan şeyi göstərir: 先生が来ました = müəllim gəldi. Yeni məlumatı vurğulayır; は isə artıq bəlli mövzunu.","en":"Marks who does the action or what exists: 先生が来ました = a teacher came. Introduces new information, while は marks a known topic.","ru":"Отмечает деятеля или то, что существует: 先生が来ました = пришёл учитель. Вводит новую информацию; は – уже известную тему."}},"けがす":{"b":"汚す (けがす)","p":"v","m":{"az":"murdarlamaq, ləkələmək, təhqir etmək","en":"to defile, stain, dishonor","ru":"осквернять, пятнать, позорить"},"n":{"az":"けがす adətən paklığı və ya şərəfi ləkələməkdir; 汚して oxunuşu けがして və ya よごして ola bilər.","en":"けがす often means to defile purity or honor; 汚して can be read けがして or よごして.","ru":"けがす часто означает осквернять чистоту или честь; 汚して читается けがして или よごして."}},"ここ":{"b":"ここ","p":"pr","m":{"az":"bura; burada","en":"here; this place","ru":"здесь; это место"},"n":{"az":"Danışana yaxın yeri bildirir.","en":"Refers to a place near the speaker.","ru":"Указывает на место рядом с говорящим."}},"こと":{"b":"こと","p":"n","m":{"az":"iş; hadisə; məsələ","en":"thing; matter; event","ru":"дело; событие; обстоятельство"},"n":{"az":"Felə qoşularaq hərəkəti isimləşdirir: 読むこと oxumaq hərəkəti.","en":"It nominalizes verbs: 読むこと means the act of reading.","ru":"Превращает глагол в существительное: 読むこと означает чтение."}},"この":{"b":"この","p":"dm","m":{"az":"bu","en":"this","ru":"этот"},"n":{"az":"この大学 = bu universitet.","en":"この大学 = this university.","ru":"この大学 = этот университет."}},"しかし":{"b":"しかし (しかし)","p":"cj","m":{"az":"lakin; ancaq","en":"however; nevertheless","ru":"однако; тем не менее"},"n":{"az":"Əvvəlki fikrə zidd olan yeni fikri təqdim edir.","en":"Introduces a statement contrasting with the previous one.","ru":"Вводит мысль, противопоставленную предыдущей."}},"すぎる":{"b":"過ぎる (すぎる)","p":"v","m":{"az":"keçmək, həddi aşmaq","en":"to pass, to exceed","ru":"проходить, превышать"},"n":{"az":"Feildən və ya sifətdən sonra 〜すぎる həddindən artıq olmağı bildirir.","en":"After a verb or adjective stem, 〜すぎる means doing or being something too much.","ru":"После основы глагола или прилагательного 〜すぎる означает чрезмерность."}},"すぐ":{"b":"すぐ","p":"ad","m":{"az":"tez, dərhal","en":"soon, immediately","ru":"сразу, скоро"},"n":{"az":"すぐに = dərhal.","en":"すぐに = right away.","ru":"すぐに = сразу."}},"する":{"b":"する","p":"v","m":{"az":"etmək; (səs, iy) gəlmək","en":"to do; (a sound) to be heard","ru":"делать; (о звуке) слышаться"},"n":{"az":"Ən çox işlənən feil. 音がしました = səs gəldi. 〜ようとしました = ...-mağa çalışdı.","en":"Most common verb. 音がしました = there was a sound. 〜ようとしました = tried to ...","ru":"Самый частый глагол. 音がしました = раздался звук. 〜ようとしました = попытался ..."}},"そう":{"b":"そう","p":"ad","m":{"az":"elə; belə","en":"so; that way","ru":"так"},"n":{"az":"そうです təsdiq, そうします isə deyilən şəkildə hərəkət etməyi bildirir.","en":"そうです confirms something; そうします means to do it that way.","ru":"そうです выражает подтверждение, а そうします означает сделать именно так."}},"そこ":{"b":"そこ","p":"pr","m":{"az":"ora","en":"there","ru":"там"},"n":{"az":"Dinləyiciyə yaxın və ya söhbətdə artıq qeyd olunan yeri göstərir.","en":"Refers to a place near the listener or already mentioned.","ru":"Обозначает место рядом с собеседником или уже упомянутое место."}},"そして":{"b":"そして","p":"cj","m":{"az":"və, sonra","en":"and, then","ru":"и, затем"}},"その":{"b":"その","p":"dm","m":{"az":"o (bəhs edilən)","en":"that (the one mentioned)","ru":"тот, этот (упомянутый)"},"n":{"az":"その時 = o vaxt, elə bu an.","en":"その時 = at that moment.","ru":"その時 = в тот момент."}},"それ":{"b":"それ","p":"pr","m":{"az":"o; həmin şey","en":"that; that thing","ru":"то; эта вещь"},"n":{"az":"Dinləyənə yaxın və ya əvvəl qeyd edilmiş şeyi bildirir.","en":"Refers to something near the listener or already mentioned.","ru":"Указывает на предмет рядом со слушающим или на уже упомянутое."}},"ぞ":{"b":"ぞ","p":"pt","m":{"az":"ha, bax, bil ki","en":"I tell you, emphatic ending","ru":"же, знай, вот"},"n":{"az":"Cümləsonu hissəciyidir; güclü vurğu verir və kobud və ya kişi danışığı kimi səslənə bilər.","en":"A sentence-final particle adding strong emphasis, often sounding rough or masculine.","ru":"Конечная частица с сильным акцентом, часто звучит грубо или по-мужски."}},"たたく":{"b":"叩く (たたく)","p":"v","m":{"az":"döymək; vurmaq","en":"to knock; to hit","ru":"стучать; ударять"},"n":{"az":"ドアをたたく qapını döymək deməkdir.","en":"ドアをたたく means to knock on a door.","ru":"ドアをたたく означает стучать в дверь."}},"だ":{"b":"だ (だ)","p":"cp","m":{"az":"-dır, -dir; olmaq","en":"to be; is, am, are","ru":"быть; являться"},"n":{"az":"なら şərt formasıdır: 学生なら, əgər tələbədirsə.","en":"なら is a conditional form: 学生なら means if someone is a student.","ru":"なら является условной формой: 学生なら означает если он студент."}},"だけ":{"b":"だけ","p":"pt","m":{"az":"yalnız, ancaq","en":"only, just","ru":"только"},"n":{"az":"一度だけ = bircə dəfə; まんなかの星だけ = yalnız ortadakı ulduz.","en":"一度だけ = just once.","ru":"一度だけ = только один раз."}},"ちょっと":{"b":"ちょっと","p":"ad","m":{"az":"bir az; bir an","en":"a little; a moment","ru":"немного; минутку"},"n":{"az":"Xahişi yumşaldır: ちょっと待ってください; tərəddüdlü cavabda nəzakətli imtina da ola bilər.","en":"Softens requests: ちょっと待ってください; in a hesitant reply it can signal a polite refusal.","ru":"Смягчает просьбы: ちょっと待ってください; в нерешительном ответе может выражать вежливый отказ."}},"つける":{"b":"付ける (つける)","p":"v","m":{"az":"qoymaq (ad), taxmaq","en":"to give (a name), attach","ru":"давать (имя), прикреплять"},"n":{"az":"名前をつける = ad qoymaq.","en":"名前をつける = give a name.","ru":"名前をつける = дать имя."}},"つながる":{"b":"繋がる (つながる)","p":"v","m":{"az":"bağlanmaq, əlaqəli olmaq","en":"to be connected, be linked","ru":"соединяться, быть связанным"},"n":{"az":"自動詞dir; 繋ぐ (birləşdirmək) ilə cütdür, つながっていました keçmişdə bağlı vəziyyəti bildirir.","en":"Intransitive; pairs with 繋ぐ, and つながっていました describes a past connected state.","ru":"Непереходный глагол; пара к 繋ぐ, а つながっていました обозначает состояние связи в прошлом."}},"で":{"b":"で","p":"pt","m":{"az":"-da/-də (hərəkətin yeri); ilə (vasitə)","en":"at, in (place of action); with, by (means)","ru":"в, на (место действия); с помощью"},"n":{"az":"Hərəkətin baş verdiyi yer: 山で竹を切る = dağda bambuk kəsmək; 庭で泣く = bağçada ağlamaq. Vasitə: 両手で = iki əllə. Varlıq üçün に işlənir, hərəkət üçün で.","en":"Place where an action happens: 山で = on the mountain; means: 両手で = with both hands. Existence uses に, actions use で.","ru":"Место действия: 山で = в горах; средство: 両手で = обеими руками. Для существования – に, для действия – で."}},"できる":{"b":"できる","p":"v","m":{"az":"bacarmaq; hazır olmaq","en":"be able to; be ready","ru":"мочь; быть готовым"},"n":{"az":"Bacarığı 日本語ができる, tamamlanmanı isə ご飯ができる kimi ifadə edir.","en":"Expresses ability in 日本語ができる and completion in ご飯ができる.","ru":"Выражает умение в 日本語ができる и готовность в ご飯ができる."}},"です":{"b":"です","p":"cp","m":{"az":"-dır, -dir (nəzakətli)","en":"is, am, are (polite)","ru":"есть, является (вежл.)"},"n":{"az":"İsmin sonunda gəlir: 学生です = Tələbəyəm / tələbədir. İndiki zaman, təsdiq, nəzakətli forma. Şəxs bildirmir: kontekstdən anlaşılır.","en":"Ends a noun sentence: 学生です = I am / he is a student. Present, affirmative, polite. It shows no person: context tells.","ru":"Завершает именное предложение: 学生です = я студент / он студент. Настоящее время, утверждение, вежливо. Лицо не выражает."}},"でも":{"b":"でも","p":"cj","m":{"az":"amma, lakin","en":"but","ru":"но"},"n":{"az":"Cümlənin əvvəlində gəlir və əvvəlki fikrə zidd fikir gətirir.","en":"Starts a sentence and introduces a contrast.","ru":"Начинает предложение и вводит противопоставление."}},"と":{"b":"と","p":"pt","m":{"az":"ilə; (sitat) deyə","en":"and, with; (quote marker)","ru":"и, с; (цитата)"},"n":{"az":"İki mənası var: 1) おじいさんとおばあさん = baba və nənə; 2) sitatdan sonra: 「森です」と言いました = «Moriyəm» dedi. 〜と思う = ...deyə düşünmək. Feildən sonra (開けると) isə 'edəndə, ...-ınca' deməkdir.","en":"Two main uses: 1) 'and' between nouns; 2) after a quote: 「…」と言いました = said \"…\". After a verb (開けると) it means 'when/as soon as'.","ru":"Основные значения: 1) 'и' между существительными; 2) после цитаты: 「…」と言いました = сказал «…». После глагола (開けると) – 'когда/как только'."}},"とき":{"b":"時 (とき)","p":"n","m":{"az":"vaxt, an","en":"time, moment","ru":"время, момент"}},"ところ":{"b":"所 (ところ)","p":"n","m":{"az":"yer; məqam; an","en":"place; point; moment","ru":"место; момент"},"n":{"az":"Vるところ başlanmaq üzrə olan, Vているところ davam edən, Vたところ isə yenicə bitmiş hərəkətdir.","en":"Vるところ means about to do, Vているところ means in progress, and Vたところ means just finished.","ru":"Vるところ означает собираюсь сделать, Vているところ процесс, а Vたところ только что закончил."}},"とても":{"b":"とても","p":"ad","m":{"az":"çox","en":"very","ru":"очень"}},"なさる":{"b":"なさる","p":"v","m":{"az":"etmək (hörmətli forma)","en":"to do (honorific)","ru":"делать (уважительная форма)"},"n":{"az":"する felinin hörmətli formasıdır; なさい əmr və göstərişlərdə işlənir.","en":"Honorific form of する; なさい is used for instructions and commands.","ru":"Уважительная форма する; なさい используется в указаниях и приказах."}},"なる":{"b":"なる","p":"v","m":{"az":"olmaq, çevrilmək","en":"to become","ru":"становиться"},"n":{"az":"N/na-sifət + に なる; i-sifət: い → く なる (大きくなる = böyümək).","en":"N/na-adj + に なる; i-adj: い → く なる (大きくなる = grow big).","ru":"N/na-прил. + に なる; i-прил.: い → く なる (大きくなる = вырасти)."}},"なん":{"b":"何 (なん)","p":"pr","m":{"az":"nə","en":"what","ru":"что"},"n":{"az":"何 なん və なに kimi oxunur; məsələn, 何ですか なんですか, 何を なにを.","en":"何 is read なん or なに depending on context, as in 何ですか and 何を.","ru":"何 читается как なん или なに в зависимости от контекста, например в 何ですか и 何を."}},"に":{"b":"に","p":"pt","m":{"az":"-a/-ə; -da/-də; -ı (hədəf)","en":"to; at, in; (target)","ru":"в, на; к (цель)"},"n":{"az":"Çoxmənalı hissəcik: yer (教室の前に立つ = sinifin qabağında dayanmaq), istiqamət/hədəf (大学に来る = universitetə gəlmək), zaman (二年前に = iki il əvvəl), nəticə (静かになる). Mənanı feil müəyyən edir.","en":"Many uses: location of existence/position, destination or target, a point in time, the result of a change. The verb decides which.","ru":"Многозначная частица: место (стоять перед), направление/цель (прийти в университет), время (два года назад), результат изменения. Значение задаёт глагол."}},"ね":{"b":"ね","p":"pt","m":{"az":"elə deyilmi?; hə?","en":"right?; isn't it?","ru":"правда?; ведь"},"n":{"az":"Cümlə sonunda təsdiq və ortaq hiss bildirir, məsələn 寒いですね, əmri yumşaldır, məsələn 来てね, danışıqda isə 私はね kimi diqqət çəkir.","en":"At sentence end it seeks agreement or shares a feeling, as in 寒いですね, softens requests, as in 来てね, and conversationally draws attention, as in 私はね.","ru":"В конце фразы выражает ожидание согласия или общее чувство, как в 寒いですね, смягчает просьбу, как в 来てね, и привлекает внимание, как в 私はね."}},"の":{"b":"の","p":"pt","m":{"az":"-ın, -in (yiyəlik); iki ismi bağlayır","en":"of, -'s; links two nouns","ru":"связывает два существительных (род. падеж)"},"n":{"az":"N1 の N2: N1 N2-ni təyin edir. さくら大学の学生 = Sakura Universitetinin tələbəsi; ロボットの先生 = robot müəllim (növ bildirir).","en":"N1 の N2: N1 describes N2. さくら大学の学生 = a student of Sakura University; ロボットの先生 = a robot teacher (kind).","ru":"N1 の N2: N1 определяет N2. さくら大学の学生 = студент университета Сакура; ロボットの先生 = учитель-робот (вид)."}},"は":{"b":"は (wa)","p":"pt","m":{"az":"mövzu hissəciyi","en":"topic marker","ru":"частица темы"},"n":{"az":"Cümlənin nədən bəhs etdiyini göstərir. Yazılışı は, amma hissəcik kimi 'wa' oxunur: わたしは = 'mənə gəlincə / mən'.","en":"Marks what the sentence is about. Written は but read 'wa' as a particle: わたしは = 'as for me'.","ru":"Отмечает, о чём предложение. Пишется は, но как частица читается 'wa': わたしは = 'что касается меня'."}},"ひも":{"b":"ひも (ひも)","p":"n","m":{"az":"ip; bağ","en":"string; cord","ru":"шнурок; верёвочка"}},"ひらひら":{"b":"ひらひら","p":"ad","m":{"az":"yellənərək, süzülərək","en":"flutteringly, lightly floating","ru":"порхая, развеваясь"},"n":{"az":"Yüngül şeylərin havada dalğalanmasını bildirir; 葉がひらひら落ちる yarpaqların süzülərək düşməsidir.","en":"Describes light fluttering; 葉がひらひら落ちる means leaves flutter down.","ru":"Описывает лёгкое порхание; 葉がひらひら落ちる означает, что листья плавно кружатся при падении."}},"びっくり":{"b":"びっくり","p":"ad","m":{"az":"təəccüb; diksinmə","en":"surprise; startlement","ru":"удивление; испуг"},"n":{"az":"びっくりする təəccüblənmək və ya qəfil diksinmək deməkdir.","en":"びっくりする means to be surprised or startled.","ru":"びっくりする означает удивиться или вздрогнуть от неожиданности."}},"へ":{"b":"へ (e)","p":"pt","m":{"az":"-a/-ə (istiqamət)","en":"to, toward","ru":"к, в (направление)"},"n":{"az":"İstiqamət bildirir: 家へ帰る = evə qayıtmaq. Hissəcik kimi 'e' oxunur.","en":"Shows direction: 家へ帰る = go home. Read 'e' as a particle.","ru":"Направление: 家へ帰る = вернуться домой. Как частица читается 'e'."}},"ほう":{"b":"方 (ほう)","p":"n","m":{"az":"tərəf, istiqamət, seçim","en":"side, direction, option","ru":"сторона, направление, вариант"},"n":{"az":"〜のほう müqayisədə üstün tutulan tərəfi bildirə bilər.","en":"〜のほう can indicate the preferred side in a comparison.","ru":"〜のほう может указывать на предпочтительный вариант при сравнении."}},"ほっと":{"b":"ほっと","p":"ad","m":{"az":"rahatlanaraq, dərindən nəfəs alaraq","en":"with relief, relievedly","ru":"с облегчением, спокойно"},"n":{"az":"ほっとする rahatlıq hiss etmək, ほっとした isə rahatladı deməkdir.","en":"ほっとする means to feel relieved, and ほっとした means felt relieved.","ru":"ほっとする означает почувствовать облегчение, а ほっとした - почувствовал облегчение."}},"ほめる":{"b":"褒める (ほめる)","p":"v","m":{"az":"tərifləmək","en":"to praise, compliment","ru":"хвалить"},"n":{"az":"他動詞dir; ほめられました məchul keçmiş formadır və təriflənmək deməkdir.","en":"Transitive; ほめられました is the polite past passive, meaning was praised.","ru":"Переходный глагол; ほめられました - вежливая прошедшая страдательная форма, означающая был похвален."}},"まず":{"b":"まず","p":"ad","m":{"az":"əvvəlcə; ilk növbədə","en":"first; to begin with","ru":"сначала; прежде всего"}},"また":{"b":"また","p":"ad","m":{"az":"yenə, təkrar","en":"again","ru":"снова"}},"まだ":{"b":"まだ","p":"ad","m":{"az":"hələ","en":"still, yet","ru":"ещё"}},"まで":{"b":"まで","p":"pt","m":{"az":"qədər, hətta","en":"until, as far as, even","ru":"до, даже"},"n":{"az":"Zaman və məkan həddini bildirir: 五時まで “saat beşə qədər”, 駅まで “stansiyaya qədər”; təəccüblü əlavəni də vurğulayır: 子どもまで “hətta uşaqlar”.","en":"Marks a time or place limit, as in 五時まで “until five” and 駅まで “as far as the station,” and surprising inclusion, as in 子どもまで “even children.”","ru":"Обозначает предел времени или места: 五時まで «до пяти», 駅まで «до станции», а также неожиданное включение: 子どもまで «даже дети»."}},"みんな":{"b":"みんな","p":"n","m":{"az":"hamı, hamısı","en":"everyone, all","ru":"все"}},"むかしむかし":{"b":"昔々 (むかしむかし)","p":"ex","m":{"az":"biri var idi, biri yox idi","en":"once upon a time","ru":"давным-давно"},"n":{"az":"Yapon nağıllarının ənənəvi başlanğıcı.","en":"The traditional opening of Japanese tales.","ru":"Традиционное начало японских сказок."}},"も":{"b":"も","p":"pt","m":{"az":"də, da (həmçinin)","en":"also, too","ru":"тоже, также"},"n":{"az":"は-nin yerinə gəlir: ケンさんも = 'Ken də'. は ilə birlikdə işlənmir.","en":"Replaces は: ケンさんも = 'Ken too'. Not used together with は.","ru":"Ставится вместо は: ケンさんも = 'Кен тоже'. Вместе с は не используется."}},"もう":{"b":"もう","p":"ad","m":{"az":"daha; artıq","en":"more; already","ru":"ещё; уже"},"n":{"az":"もう一度 = bir daha.","en":"もう一度 = once more.","ru":"もう一度 = ещё раз."}},"もちろん":{"b":"もちろん","p":"ad","m":{"az":"əlbəttə, şübhəsiz","en":"of course, certainly","ru":"конечно, разумеется"}},"もっと":{"b":"もっと","p":"ad","m":{"az":"daha, daha çox","en":"more","ru":"больше, ещё"}},"やる":{"b":"やる","p":"v","m":{"az":"etmək; yerinə yetirmək","en":"to do; to carry out","ru":"делать; выполнять"},"n":{"az":"する felinin daha qeyri-rəsmi variantıdır və kiməsə nəsə vermək mənasında da işlənir.","en":"A more informal alternative to する; it can also mean to give something to someone or an animal.","ru":"Более разговорный вариант する; также может означать давать кому-либо или животному."}},"ゆっくり":{"b":"ゆっくり","p":"ad","m":{"az":"yavaş-yavaş, tələsmədən","en":"slowly","ru":"медленно"}},"よ":{"b":"よ","p":"pt","m":{"az":"cümləsonu vurğu ədatı","en":"sentence-final emphasis particle","ru":"конечная усилительная частица"},"n":{"az":"Cümlənin sonunda yeni məlumatı, əminliyi və ya xəbərdarlığı vurğulayır: ここですよ “Buradadır”, 危ないよ “Ehtiyatlı ol”; 行こうよ kimi ifadələrdə çağırışı gücləndirir.","en":"At sentence end, it stresses information, assurance, or warning, as in ここですよ “It's here” and 危ないよ “Watch out,” and strengthens invitations such as 行こうよ “Let's go.”","ru":"В конце предложения подчёркивает сообщение, уверенность или предупреждение: ここですよ «Это здесь», 危ないよ «Осторожно», а также усиливает призыв: 行こうよ «Пойдём»."}},"よく":{"b":"よく","p":"ad","m":{"az":"yaxşıca, diqqətlə","en":"well, carefully","ru":"хорошо, внимательно"}},"よし":{"b":"よし","p":"in","m":{"az":"yaxşı, oldu, hə","en":"all right, okay, good","ru":"хорошо, ладно, отлично"},"n":{"az":"Qərar verməzdən və ya işə başlamazdan əvvəl qətiyyət bildirən nida kimi işlənir.","en":"An exclamation expressing determination or approval before taking action.","ru":"Междометие, выражающее решимость или одобрение перед действием."}},"より":{"b":"より","p":"pt","m":{"az":"-dan/-dən daha (müqayisə)","en":"than","ru":"чем"},"n":{"az":"さっきより明るく = bayaqkından daha parlaq.","en":"さっきより明るく = brighter than before.","ru":"さっきより明るく = ярче, чем раньше."}},"わかる":{"b":"分かる (わかる)","p":"v","m":{"az":"başa düşmək; anlamaq","en":"understand","ru":"понимать"},"n":{"az":"Başa düşülən şey adətən が ilə göstərilir: 日本語が分かる.","en":"What is understood usually takes が: 日本語が分かる.","ru":"То, что понимают, обычно оформляется частицей が: 日本語が分かる."}},"わし":{"b":"わし","p":"pr","m":{"az":"mən","en":"I, me","ru":"я"},"n":{"az":"Qeyri-rəsmi birinci şəxs əvəzliyidir; hekayələrdə çox vaxt yaşlı kişi obrazları işlədir.","en":"An informal first-person pronoun often used by elderly male characters in stories.","ru":"Неформальное местоимение первого лица, часто используемое пожилыми мужскими персонажами."}},"わる":{"b":"悪い (わるい)","p":"ai","m":{"az":"pis, yaramaz","en":"bad, naughty","ru":"плохой, непослушный"},"n":{"az":"悪い い-sifətdir; わるな ayrıca standart na-sifət deyil, わるな isə 悪いな ifadəsinin ixtisarı və ya başqa felin qadağa forması ola bilər.","en":"悪い is an i-adjective; わるな is not a standard na-adjective and may be a clipped expression or a prohibitive verb form.","ru":"悪い - прилагательное на い; わるな не является стандартным na-прилагательным и может быть сокращением или запретительной формой глагола."}},"を":{"b":"を (o)","p":"pt","m":{"az":"təsirlik hissəcik (-ı, -i)","en":"object marker","ru":"частица прямого объекта"},"n":{"az":"Feilin təsir etdiyi əşyanı göstərir: かばんを持つ = çantanı tutmaq. Yazılışı を, oxunuşu 'o'.","en":"Marks the direct object: かばんを持つ = hold a bag. Written を, read 'o'.","ru":"Отмечает прямое дополнение: かばんを持つ = держать сумку. Пишется を, читается 'o'."}},"タケシさん":{"b":"タケシさん (たけしさん)","p":"nm","m":{"az":"Takeşi bəy","en":"Takeshi, Mr. Takeshi","ru":"Такэси, господин Такэси"},"n":{"az":"さん adın sonunda nəzakətli müraciət bildirir və cinsdən asılı deyil.","en":"さん is a polite name suffix and is not gender-specific.","ru":"さん - вежливый суффикс после имени, не зависящий от пола."}},"ドア":{"b":"ドア","p":"n","m":{"az":"qapı","en":"door","ru":"дверь"}},"ハル":{"b":"ハル","p":"nm","m":{"az":"Haru","en":"Haru","ru":"Хару"}},"ミオ":{"b":"ミオ (ミオ)","p":"nm","m":{"az":"Mio; şəxs adı","en":"Mio; personal name","ru":"Мио; личное имя"}},"一":{"b":"一 (いち)","p":"nu","m":{"az":"bir","en":"one","ru":"один"}},"一人":{"b":"一人 (ひとり)","p":"n","m":{"az":"tək, bir nəfər","en":"alone; one person","ru":"один (человек)"},"n":{"az":"一人で = təkbaşına.","en":"一人で = alone.","ru":"一人で = в одиночку."}},"一度":{"b":"一度 (いちど)","p":"n","m":{"az":"bir dəfə","en":"once","ru":"один раз"}},"一週間":{"b":"一週間 (いっしゅうかん)","p":"ex","m":{"az":"bir həftə","en":"one week","ru":"одна неделя"},"n":{"az":"Müddət bildirir, 一週間に一回 həftədə bir dəfə deməkdir.","en":"Expresses duration, and 一週間に一回 means once a week.","ru":"Обозначает длительность, 一週間に一回 значит один раз в неделю."}},"七歳":{"b":"七歳 (ななさい)","p":"nu","m":{"az":"yeddi yaş","en":"seven years old","ru":"семь лет"},"n":{"az":"Yaş bildirərkən 七 adətən なな oxunur: ななさい.","en":"For age, 七 is normally read なな: ななさい.","ru":"При указании возраста 七 обычно читается なな: ななさい."}},"三":{"b":"三 (さん)","p":"nu","m":{"az":"üç","en":"three","ru":"три"}},"三日":{"b":"三日 (みっか)","p":"nu","m":{"az":"ayın üçüncü günü, üç gün","en":"third day of the month, three days","ru":"третье число месяца, три дня"},"n":{"az":"Tarix və müddət bildirir, 三日 みっか oxunur.","en":"Used for a date or duration, pronounced みっか.","ru":"Обозначает дату или длительность, читается みっか."}},"三日目":{"b":"三日目 (みっかめ)","p":"n","m":{"az":"üçüncü gün","en":"third day","ru":"третий день"},"n":{"az":"目 burada günlərin sıra nömrəsini bildirir.","en":"目 marks ordinal position, here the third day.","ru":"目 обозначает порядковый номер, здесь третий день."}},"上":{"b":"上 (うえ)","p":"n","m":{"az":"üst","en":"top, above","ru":"верх, на"},"n":{"az":"N の 上 = N-in üstü.","en":"N の 上 = on top of N.","ru":"N の 上 = на N."}},"上がる":{"b":"上がる (あがる)","p":"v","m":{"az":"qalxmaq","en":"to go up, rise","ru":"подниматься"}},"上手":{"b":"上手 (じょうず)","p":"an","m":{"az":"bacarıqlı, yaxşı bacaran","en":"skillful, good at","ru":"умелый, хорошо умеющий"},"n":{"az":"な-sifətdir: ピアノが上手です = pianoda yaxşı çalır.","en":"A na-adjective: ピアノが上手です = is good at playing piano.","ru":"な-прилагательное: ピアノが上手です = хорошо играет на пианино."}},"下":{"b":"下 (した)","p":"n","m":{"az":"alt, aşağı","en":"below, under","ru":"низ, под"},"n":{"az":"その下に = onun altına.","en":"その下に = under it.","ru":"その下に = под этим."}},"下ろす":{"b":"下ろす (おろす)","p":"v","m":{"az":"aşağı endirmək; düşürmək","en":"to lower; to unload","ru":"опускать; выгружать"},"n":{"az":"下ろす nəyisə endirmək, 降りる isə nəqliyyatdan düşmək deməkdir.","en":"下ろす means to lower or unload something, while 降りる means to get off a vehicle.","ru":"下ろす означает опускать или выгружать, а 降りる - выходить из транспорта."}},"中":{"b":"中 (なか)","p":"n","m":{"az":"iç","en":"inside","ru":"внутри"},"n":{"az":"N の 中 = N-in içi.","en":"N の 中 = inside N.","ru":"N の 中 = внутри N."}},"丸い":{"b":"丸い (まるい)","p":"ai","m":{"az":"yumru, dairəvi","en":"round","ru":"круглый"},"n":{"az":"月が丸くなる = Ay bədirlənir.","en":"月が丸くなる = the moon becomes full.","ru":"月が丸くなる = луна становится полной."}},"乗せる":{"b":"乗せる (のせる)","p":"v","m":{"az":"min­dirmək, üstünə qoymaq","en":"to put aboard, give a ride, place on","ru":"сажать в транспорт, класть сверху"},"n":{"az":"他動詞dir; 乗る (minmək) ilə cütdür, 乗せろ isə kobud əmr formasıdır.","en":"Transitive; pairs with 乗る, and 乗せろ is its blunt imperative form.","ru":"Переходный глагол; пара к 乗る, а 乗せろ - грубая повелительная форма."}},"乗る":{"b":"乗る (のる)","p":"v","m":{"az":"minmək","en":"board, ride","ru":"садиться в транспорт, ехать"},"n":{"az":"Nəqliyyat vasitəsi に ilə işlənir: 電車に乗る “qatara minmək”.","en":"The vehicle takes に: 電車に乗る means “board a train.”","ru":"Транспорт обозначается с に: 電車に乗る «сесть в поезд»."}},"二人":{"b":"二人 (ふたり)","p":"n","m":{"az":"iki nəfər, ikisi","en":"two people","ru":"двое"},"n":{"az":"İnsan sayğacı: 一人 (ひとり), 二人 (ふたり), 三人 (さんにん).","en":"People counter: 一人, 二人, 三人.","ru":"Счёт людей: 一人, 二人, 三人."}},"人":{"b":"人 (ひと)","p":"n","m":{"az":"adam, insan","en":"person","ru":"человек"},"n":{"az":"Tək işlənəndə ひと oxunur. Ölkə adından sonra じん olur: 日本人 (にほんじん) = yapon.","en":"Read ひと on its own. After a country it becomes じん: 日本人 = Japanese person.","ru":"Отдельно читается ひと. После названия страны – じん: 日本人 = японец."}},"人たち":{"b":"人たち (ひとたち)","p":"n","m":{"az":"adamlar, camaat","en":"people","ru":"люди"}},"今度":{"b":"今度 (こんど)","p":"n","m":{"az":"bu dəfə, gələn dəfə","en":"this time, next time","ru":"на этот раз, в следующий раз"},"n":{"az":"Kontekstdən asılı olaraq indiki və ya növbəti hadisəni bildirir.","en":"Depending on context, it refers to the present occasion or the next one.","ru":"В зависимости от контекста обозначает нынешний или следующий случай."}},"今日":{"b":"今日 (きょう)","p":"n","m":{"az":"bu gün","en":"today","ru":"сегодня"}},"仕事":{"b":"仕事 (しごと)","p":"n","m":{"az":"iş","en":"work, job","ru":"работа"}},"休む":{"b":"休む (やすむ)","p":"v","m":{"az":"istirahət etmək, işə və ya dərsə getməmək","en":"rest, take time off","ru":"отдыхать, пропускать работу или занятия"},"n":{"az":"学校を休む “dərsə getməmək”, 会社を休む isə “işə getməmək” deməkdir.","en":"学校を休む means “miss school,” and 会社を休む means “take time off work.”","ru":"学校を休む означает «пропускать занятия», а 会社を休む означает «не идти на работу»."}},"会":{"b":"会 (かい)","p":"n","m":{"az":"toplantı, yığıncaq, tədbir","en":"meeting, gathering, event","ru":"собрание, встреча, мероприятие"}},"会社":{"b":"会社 (かいしゃ)","p":"n","m":{"az":"şirkət","en":"company","ru":"компания"}},"会社員":{"b":"会社員 (かいしゃいん)","p":"n","m":{"az":"şirkət işçisi, ofis əməkdaşı","en":"company employee, office worker","ru":"сотрудник компании, офисный работник"},"n":{"az":"会社員 şirkətdə işləyən şəxsdir; konkret şirkət üçün 〜の社員 də işlənir.","en":"会社員 means a company employee; 〜の社員 identifies an employee of a specific company.","ru":"会社員 означает сотрудника компании; 〜の社員 указывает на работника конкретной фирмы."}},"住む":{"b":"住む (すむ)","p":"v","m":{"az":"yaşamaq, məskunlaşmaq","en":"to live, to reside","ru":"жить, проживать"},"n":{"az":"住んで て-formadır, 場所に住む müəyyən yerdə yaşamaq deməkdir.","en":"住んで is the te-form, and 場所に住む means to live in a place.","ru":"住んで - форма на て, 場所に住む означает жить в определённом месте."}},"何":{"b":"何 (なに・なん)","p":"pr","m":{"az":"nə","en":"what","ru":"что"},"n":{"az":"何ですか və 何時 kimi birləşmələrdə なん, 何を kimi hallarda isə なに oxunur.","en":"Read なん in expressions such as 何ですか and 何時, but なに in 何を.","ru":"Читается なん в сочетаниях 何ですか и 何時, но なに в 何を."}},"作る":{"b":"作る (つくる)","p":"v","m":{"az":"düzəltmək, yaratmaq","en":"to make","ru":"делать, создавать"},"n":{"az":"作ったのでした = (məlum oldu ki) düzəltmişdilər – izah bildirir.","en":"作ったのでした = (it turned out) they had made him.","ru":"作ったのでした = (оказалось) создали его."}},"使う":{"b":"使う (つかう)","p":"v","m":{"az":"istifadə etmək; işlətmək","en":"to use","ru":"использовать; пользоваться"},"n":{"az":"N を使う şəklində işlənir: パソコンを使う.","en":"Takes を for the object: パソコンを使う means to use a computer.","ru":"Используется с を для объекта: パソコンを使う означает пользоваться компьютером."}},"侍":{"b":"侍 (さむらい)","p":"n","m":{"az":"samuray; yapon döyüşçüsü","en":"samurai; Japanese warrior","ru":"самурай; японский воин"}},"働く":{"b":"働く (はたらく)","p":"v","m":{"az":"işləmək","en":"to work","ru":"работать"},"n":{"az":"İş yerini で göstərir: 銀行で働きます.","en":"The workplace takes で: 銀行で働きます.","ru":"Место работы обозначается через で: 銀行で働きます."}},"働ける":{"b":"働ける (はたらける)","p":"v","m":{"az":"işləyə bilmək","en":"can work","ru":"мочь работать"},"n":{"az":"働く felinin imkan formasıdır; 働け əmr formasıdır.","en":"Potential form of 働く; 働け is the imperative form.","ru":"Форма возможности от 働く; 働け является повелительной формой."}},"優しい":{"b":"優しい (やさしい)","p":"ai","m":{"az":"mehriban, mülayim","en":"kind, gentle","ru":"добрый, мягкий"},"n":{"az":"İ-sifətidir; “asan” mənasındakı 易しい ilə eyni oxunur.","en":"An i-adjective; it has the same reading as 易しい “easy.”","ru":"Прилагательное на い; читается так же, как 易しい «лёгкий»."}},"先":{"b":"先 (さき)","p":"n","m":{"az":"uc, son; qabaq","en":"end, tip; ahead","ru":"конец; впереди"},"n":{"az":"道の先 = yolun sonu.","en":"道の先 = the end of the path.","ru":"道の先 = конец дороги."}},"先生":{"b":"先生 (せんせい)","p":"n","m":{"az":"müəllim; həkim","en":"teacher; doctor","ru":"учитель; доктор"},"n":{"az":"Başqasına müraciət kimi işlənir (ミミ先生 = Mimi həkim). Özün haqqında 先生 demirsən, 教師 deyirsən.","en":"Used to address others (ミミ先生 = Doctor Mimi). Never about yourself – then you say 教師.","ru":"Используется как обращение (ミミ先生 = доктор Мими). О себе так не говорят – говорят 教師."}},"先輩":{"b":"先輩 (せんぱい)","p":"n","m":{"az":"böyük həmkar; təcrübəli yoldaş","en":"senior; experienced colleague","ru":"старший товарищ; старший коллега"},"n":{"az":"Yaşca deyil, təcrübə və ya üzvlük müddətinə görə böyük olan şəxsdir.","en":"Refers to someone senior in experience or membership, not necessarily age.","ru":"Обозначает старшего по опыту или стажу, не обязательно по возрасту."}},"光":{"b":"光 (ひかり)","p":"n","m":{"az":"işıq","en":"light","ru":"свет"}},"光る":{"b":"光る (ひかる)","p":"v","m":{"az":"parlamaq, işıq saçmaq","en":"to shine","ru":"светиться, сиять"},"n":{"az":"光るランプ = parlayan lampa: feil isimdən əvvəl təyin kimi gəlir.","en":"光るランプ = a glowing lamp: a verb before a noun describes it.","ru":"光るランプ = светящаяся лампа: глагол перед сущ. – определение."}},"入る":{"b":"入る (はいる)","p":"v","m":{"az":"girmək","en":"to enter","ru":"входить"},"n":{"az":"入り、 = girib (feilin kökü ilə bağlama).","en":"入り、 = went in and ...","ru":"入り、 = вошла и ..."}},"入れる":{"b":"入れる (いれる)","p":"v","m":{"az":"içəri qoymaq; daxil etmək","en":"to put in; to insert","ru":"класть внутрь; вставлять"},"n":{"az":"Təsirlidir: 箱に入れる; təsirsiz qarşılığı 入る-dur.","en":"Transitive: 箱に入れる; its intransitive partner is 入る.","ru":"Переходный: 箱に入れる; непереходная пара: 入る."}},"全部":{"b":"全部 (ぜんぶ)","p":"n","m":{"az":"hamısı, bütün","en":"all, everything","ru":"всё, целиком"},"n":{"az":"全部で = ümumilikdə; 全部食べました = hamısını yedim.","en":"全部で = in total; 全部食べました = ate everything.","ru":"全部で = всего; 全部食べました = съел всё."}},"出す":{"b":"出す (だす)","p":"v","m":{"az":"çıxarmaq","en":"to take out","ru":"вынимать"}},"出る":{"b":"出る (でる)","p":"v","m":{"az":"çıxmaq","en":"to go out","ru":"выходить"},"n":{"az":"庭に出る = bağçaya çıxmaq.","en":"庭に出る = go out into the garden.","ru":"庭に出る = выйти в сад."}},"初めて":{"b":"初めて (はじめて)","p":"ad","m":{"az":"ilk dəfə","en":"for the first time","ru":"впервые"}},"前":{"b":"前 (まえ)","p":"n","m":{"az":"qabaq, ön; əvvəl","en":"front; before","ru":"перед; раньше"},"n":{"az":"N の 前 = N-in qabağı. 二年前 = iki il əvvəl.","en":"N の 前 = in front of N. 二年前 = two years ago.","ru":"N の 前 = перед N. 二年前 = два года назад."}},"剣":{"b":"剣 (けん)","p":"n","m":{"az":"qılınc","en":"sword","ru":"меч"}},"力":{"b":"力 (ちから)","p":"n","m":{"az":"güc; qüvvə","en":"strength; power","ru":"сила; мощь"}},"助ける":{"b":"助ける (たすける)","p":"v","m":{"az":"kömək etmək; xilas etmək","en":"help; rescue","ru":"помогать; спасать"},"n":{"az":"Təsirli feldir və kömək edilən şəxs を ilə göstərilir; 助かる xilas olmaq deməkdir.","en":"A transitive verb with the person helped marked by を; 助かる means to be saved.","ru":"Переходный глагол: человек, которому помогают, оформляется を; 助かる означает спастись."}},"勉強":{"b":"勉強 (べんきょう)","p":"n","m":{"az":"dərs oxuma; təhsil","en":"study; learning","ru":"учёба; обучение"},"n":{"az":"勉強する = dərs oxumaq, öyrənmək.","en":"勉強する means to study.","ru":"勉強する означает учиться, изучать."}},"動く":{"b":"動く (うごく)","p":"v","m":{"az":"hərəkət etmək, işləmək","en":"to move, to operate","ru":"двигаться, работать"},"n":{"az":"I qrup feldir: 動きました = hərəkət etdi; 動かす = hərəkət etdirmək.","en":"A Group 1 verb: 動きました = moved; 動かす = to move something.","ru":"Глагол I группы: 動きました = двигался; 動かす = приводить в движение."}},"勘弁":{"b":"勘弁 (かんべん)","p":"n","m":{"az":"bağışlama; güzəşt","en":"forgiveness; letting someone off","ru":"прощение; снисхождение"},"n":{"az":"勘弁してください ifadəsi «məni bağışlayın» və ya «məni bundan azad edin» deməkdir.","en":"勘弁してください means \"please forgive me\" or \"please spare me.\"","ru":"勘弁してください означает «простите меня» или «избавьте меня от этого»."}},"厳しい":{"b":"厳しい (きびしい)","p":"ai","m":{"az":"sərt; ciddi; çətin","en":"strict; severe; harsh","ru":"строгий; суровый; тяжёлый"},"n":{"az":"い-sifətidir; insan, qayda və şərait haqqında işlənir.","en":"An i-adjective used for people, rules, or difficult conditions.","ru":"Прилагательное на い, описывающее людей, правила или тяжёлые условия."}},"友達":{"b":"友達 (ともだち)","p":"n","m":{"az":"dost","en":"friend","ru":"друг"}},"叫ぶ":{"b":"叫ぶ (さけぶ)","p":"v","m":{"az":"qışqırmaq; hayqırmaq","en":"to shout; to cry out","ru":"кричать; восклицать"}},"合わせる":{"b":"合わせる (あわせる)","p":"v","m":{"az":"uyğunlaşdırmaq, birləşdirmək","en":"to match, to combine","ru":"сочетать, соединять"},"n":{"az":"合わせる təsirli feildir; 〜に合わせる nəyəsə uyğunlaşdırmaq deməkdir.","en":"合わせる is transitive; 〜に合わせる means to adjust or match something to another thing.","ru":"合わせる переходный глагол; 〜に合わせる означает подстраивать под что-либо."}},"合図":{"b":"合図 (あいず)","p":"n","m":{"az":"işarə; siqnal","en":"signal; cue","ru":"сигнал; знак"},"n":{"az":"合図をする «işarə vermək» deməkdir.","en":"合図をする means \"to give a signal.\"","ru":"合図をする означает «подать сигнал»."}},"吉四六さん":{"b":"吉四六さん (きっちょむさん)","p":"nm","m":{"az":"cənab Kiççom","en":"Mr. Kitchomu","ru":"господин Киттём"},"n":{"az":"さん ada əlavə edilən nəzakətli müraciət şəkilçisidir.","en":"さん is a polite honorific suffix attached to a name.","ru":"さん является вежливым суффиксом обращения после имени."}},"同じ":{"b":"同じ (おなじ)","p":"an","m":{"az":"eyni","en":"same","ru":"одинаковый, тот же"},"n":{"az":"İsimdən əvvəl な almır: 同じ月 = eyni Ay.","en":"Takes no な before a noun: 同じ月 = the same moon.","ru":"Перед сущ. без な: 同じ月 = та же луна."}},"向かう":{"b":"向かう (むかう)","p":"v","m":{"az":"istiqamətlənmək; tərəfə getmək","en":"to head toward; to face","ru":"направляться; быть обращённым"},"n":{"az":"場所に向かう bir yerə doğru getmək deməkdir.","en":"場所に向かう means to head toward a place.","ru":"場所に向かう означает направляться к месту."}},"君":{"b":"君 (きみ)","p":"pr","m":{"az":"sən","en":"you (informal)","ru":"ты"},"n":{"az":"Yaxın münasibətdə və ya böyükdən kiçiyə müraciətdə işlənir, hər vəziyyətdə nəzakətli deyil.","en":"Used with close acquaintances or by seniors to juniors, and is not always polite.","ru":"Употребляется между близкими или при обращении старшего к младшему, не всегда вежливо."}},"吹く":{"b":"吹く (ふく)","p":"v","m":{"az":"əsmək; üfürmək; çalmaq","en":"to blow; to play a wind instrument","ru":"дуть; веять; играть на духовом инструменте"},"n":{"az":"風が吹く külək əsmək, 笛を吹く fleyta çalmaqdır.","en":"風が吹く means the wind blows; 笛を吹く means to play a flute.","ru":"風が吹く означает ветер дует; 笛を吹く означает играть на флейте."}},"呼ぶ":{"b":"呼ぶ (よぶ)","p":"v","m":{"az":"çağırmaq, adlandırmaq","en":"call, name","ru":"звать, называть"},"n":{"az":"Şəxs を ilə göstərilir; AをBと呼ぶ “A-nı B adlandırmaq” deməkdir.","en":"The person takes を; AをBと呼ぶ means “call A B.”","ru":"Человек обозначается с を; AをBと呼ぶ означает «называть A именем B»."}},"命令":{"b":"命令 (めいれい)","p":"n","m":{"az":"əmr; göstəriş","en":"order; command","ru":"приказ; распоряжение"},"n":{"az":"命令する «əmr vermək» deməkdir.","en":"命令する means \"to order\" or \"to command.\"","ru":"命令する означает «приказывать»."}},"困る":{"b":"困る (こまる)","p":"v","m":{"az":"çətin vəziyyətdə qalmaq; çətinlik çəkmək","en":"be in trouble; be at a loss","ru":"оказаться в затруднении"},"n":{"az":"困っている hazırda çətin vəziyyətdə olmağı bildirir; səbəb に ilə göstərilə bilər.","en":"困っている describes being in difficulty; the cause can be marked by に.","ru":"困っている описывает состояние затруднения; причина может оформляться に."}},"地主":{"b":"地主 (じぬし)","p":"n","m":{"az":"torpaq sahibi; mülkədar","en":"landowner; landlord","ru":"землевладелец; помещик"}},"声":{"b":"声 (こえ)","p":"n","m":{"az":"səs (insan, heyvan)","en":"voice","ru":"голос"}},"夜":{"b":"夜 (よる)","p":"n","m":{"az":"gecə","en":"night","ru":"ночь"}},"大きい":{"b":"大きい (おおきい)","p":"ai","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"大きくなる = böyümək (い → く + なる).","en":"大きくなる = grow up.","ru":"大きくなる = вырасти."}},"大きな":{"b":"大きな (おおきな)","p":"dm","m":{"az":"böyük","en":"big","ru":"большой"},"n":{"az":"Yalnız isimdən əvvəl gəlir; 大きい ilə eyni mənadadır.","en":"Only before a noun; same as 大きい.","ru":"Только перед сущ.; то же, что 大きい."}},"大好き":{"b":"大好き (だいすき)","p":"an","m":{"az":"çox sevimli, çox xoşlamaq","en":"to love, to like very much","ru":"очень любить, обожать"},"n":{"az":"な-sifətdir: 音楽が大好きです = musiqini çox sevirəm.","en":"A na-adjective: 音楽が大好きです = I love music.","ru":"な-прилагательное: 音楽が大好きです = я очень люблю музыку."}},"大笑い":{"b":"大笑い (おおわらい)","p":"n","m":{"az":"qəhqəhə; bərkdən gülmə","en":"loud laughter; hearty laugh","ru":"громкий смех; хохот"},"n":{"az":"大笑いする «qəhqəhə çəkmək» deməkdir.","en":"大笑いする means \"to laugh heartily.\"","ru":"大笑いする означает «громко хохотать»."}},"始まる":{"b":"始まる (はじまる)","p":"v","m":{"az":"başlamaq","en":"to begin; to start","ru":"начинаться"},"n":{"az":"Təsirsizdir: 祭りが始まります; təsirli qarşılığı 始める-dir.","en":"Intransitive: 祭りが始まります; its transitive partner is 始める.","ru":"Непереходный: 祭りが始まります; переходная пара: 始める."}},"始める":{"b":"始める (はじめる)","p":"v","m":{"az":"başlamaq, başlatmaq","en":"to begin, to start something","ru":"начинать"},"n":{"az":"Təsirli feldir, 勉強を始めます dərsə başlamaqdır, təsirsiz qarşılığı 始まる-dur.","en":"Transitive: 勉強を始めます means start studying, while 始まる is intransitive.","ru":"Переходный глагол: 勉強を始めます - начать учёбу, непереходный вариант 始まる."}},"娘":{"b":"娘 (むすめ)","p":"n","m":{"az":"qız övladı, gənc qız","en":"daughter, young woman","ru":"дочь, девушка"},"n":{"az":"Başqasının qız övladı haqqında nəzakətlə 娘さん deyilir.","en":"娘さん is a polite way to refer to someone else's daughter.","ru":"娘さん является вежливым обозначением чужой дочери."}},"子":{"b":"子 (こ)","p":"n","m":{"az":"uşaq; övlad","en":"child","ru":"ребёнок"},"n":{"az":"わたしの子 = mənim övladım.","en":"わたしの子 = my child.","ru":"わたしの子 = мой ребёнок."}},"子ども":{"b":"子ども (こども)","p":"n","m":{"az":"uşaq","en":"child","ru":"ребёнок"}},"子どもたち":{"b":"子どもたち (こどもたち)","p":"n","m":{"az":"uşaqlar","en":"children","ru":"дети"},"n":{"az":"たち insanları və bəzən canlıları bildirən sözlərə cəm və ya qrup mənası verir.","en":"たち marks a plural or group, mainly with words for people and sometimes other living beings.","ru":"たち обозначает множественность или группу, главным образом у слов, называющих людей, иногда других живых существ."}},"学校":{"b":"学校 (がっこう)","p":"n","m":{"az":"məktəb","en":"school","ru":"школа"}},"孫":{"b":"孫 (まご)","p":"n","m":{"az":"nəvə","en":"grandchild","ru":"внук; внучка"}},"守る":{"b":"守る (まもる)","p":"v","m":{"az":"qorumaq; qaydaya əməl etmək","en":"to protect; to obey","ru":"защищать; соблюдать"},"n":{"az":"約束を守る sözünə əməl etməkdir; 守らなければ zərurət bildirən quruluşda işlənir.","en":"約束を守る means to keep a promise; 守らなければ is used in obligation patterns.","ru":"約束を守る означает сдержать обещание; 守らなければ используется в конструкциях обязанности."}},"安全":{"b":"安全 (あんぜん)","p":"n","m":{"az":"təhlükəsizlik; təhlükəsiz vəziyyət","en":"safety; security","ru":"безопасность"},"n":{"az":"安全な şəklində な-sifəti kimi işlənir.","en":"Also functions as a na-adjective in 安全な.","ru":"Также употребляется как прилагательное на な в форме 安全な."}},"実":{"b":"実 (み)","p":"n","m":{"az":"meyvə, bar, toxum","en":"fruit, berry, seed","ru":"плод, ягода, семя"},"n":{"az":"実がなる - ağacın və ya bitkinin bar verməsi.","en":"実がなる means for a tree or plant to bear fruit.","ru":"実がなる означает плодоносить."}},"客席":{"b":"客席 (きゃくせき)","p":"n","m":{"az":"tamaşaçı yerləri; sərnişin oturacaqları","en":"audience seating; passenger seats","ru":"зрительские места; пассажирские сиденья"}},"家":{"b":"家 (いえ)","p":"n","m":{"az":"ev","en":"house, home","ru":"дом"}},"小さな":{"b":"小さな (ちいさな)","p":"dm","m":{"az":"balaca, kiçik","en":"small, little","ru":"маленький"},"n":{"az":"Yalnız isimdən əvvəl gəlir (小さな音). Mənaca 小さい ilə eynidir.","en":"Only used before a noun; same meaning as 小さい.","ru":"Только перед существительным; то же, что 小さい."}},"小屋":{"b":"小屋 (こや)","p":"n","m":{"az":"daxma, kiçik ev","en":"hut, shed","ru":"хижина, сарай"}},"少し":{"b":"少し (すこし)","p":"ad","m":{"az":"bir az","en":"a little","ru":"немного"}},"山":{"b":"山 (やま)","p":"n","m":{"az":"dağ","en":"mountain","ru":"гора"}},"席":{"b":"席 (せき)","p":"n","m":{"az":"yer; oturacaq yeri","en":"seat; place","ru":"место"},"n":{"az":"Nəqliyyatda, sinifdə və ya masada bir şəxsin yerini bildirə bilər.","en":"Can mean someone's place on transport, in class, or at a table.","ru":"Может обозначать чьё-либо место в транспорте, классе или за столом."}},"帰り道":{"b":"帰り道 (かえりみち)","p":"n","m":{"az":"qayıdış yolu; evə gedən yol","en":"way back; way home","ru":"обратный путь; дорога домой"}},"帰る":{"b":"帰る (かえる)","p":"v","m":{"az":"qayıtmaq (evə, öz yerinə)","en":"to return home","ru":"возвращаться"},"n":{"az":"家へ帰るとちゅうで = evə qayıdarkən yolda.","en":"家へ帰るとちゅうで = on the way home.","ru":"家へ帰るとちゅうで = по дороге домой."}},"度":{"b":"度 (ど／たび)","p":"nu","m":{"az":"dəfə; dərəcə","en":"time, occurrence; degree","ru":"раз; градус"},"n":{"az":"Saylardan sonra adətən ど oxunur: 一度 bir dəfə, 三十度 otuz dərəcə; この度 ifadəsində たび oxunur.","en":"After numbers it is usually ど: 一度 once, 三十度 thirty degrees; in この度 it is たび.","ru":"После чисел обычно читается ど: 一度 один раз, 三十度 тридцать градусов; в この度 читается たび."}},"庭":{"b":"庭 (にわ)","p":"n","m":{"az":"bağça, həyət","en":"garden, yard","ru":"сад, двор"}},"引く":{"b":"引く (ひく)","p":"v","m":{"az":"çəkmək, dartmaq","en":"to pull, to draw","ru":"тянуть, тащить"},"n":{"az":"引く qapını çəkmək, xətt çəkmək və ya lüğətdə söz axtarmaq mənalarında işlənə bilər.","en":"引く can mean to pull a door, draw a line, or look up a word in a dictionary.","ru":"引く может означать тянуть дверь, проводить линию или искать слово в словаре."}},"引ける":{"b":"引ける (ひける)","p":"v","m":{"az":"çəkə bilmək; dartmağı bacarmaq","en":"can pull; can draw","ru":"мочь тянуть; уметь натягивать"},"n":{"az":"引く felinin imkan formasıdır; 引けません nəzakətli inkar formasıdır.","en":"Potential form of 引く; 引けません is its polite negative.","ru":"Форма возможности от 引く; 引けません является вежливым отрицанием."}},"弟子":{"b":"弟子 (でし)","p":"n","m":{"az":"şagird; ustanın yetirməsi","en":"disciple; apprentice","ru":"ученик; подмастерье"}},"弱い":{"b":"弱い (よわい)","p":"ai","m":{"az":"zəif; gücsüz","en":"weak; feeble","ru":"слабый; бессильный"},"n":{"az":"İ-sifətdir, zərf forması 弱く olur.","en":"An i-adjective whose adverbial form is 弱く.","ru":"И-прилагательное, наречная форма 弱く."}},"強い":{"b":"強い (つよい)","p":"ai","m":{"az":"güclü, qüvvətli","en":"strong, powerful","ru":"сильный"},"n":{"az":"い-sifətdir; əksi 弱い - zəif.","en":"An i-adjective; its opposite is 弱い, weak.","ru":"Это i-прилагательное; антоним 弱い - слабый."}},"影":{"b":"影 (かげ)","p":"n","m":{"az":"kölgə; siluet","en":"shadow; silhouette","ru":"тень; силуэт"}},"待つ":{"b":"待つ (まつ)","p":"v","m":{"az":"gözləmək","en":"wait for","ru":"ждать"},"n":{"az":"Gözlənilən şəxs və ya şey を ilə işlənir; て-forması 待って olur.","en":"The person or thing awaited takes を; the て-form is 待って.","ru":"Тот, кого ждут, или то, чего ждут, обозначается с を; форма на て: 待って."}},"後ろ":{"b":"後ろ (うしろ)","p":"n","m":{"az":"arxa, arxa tərəf","en":"back, behind","ru":"задняя сторона, позади"},"n":{"az":"Nの後ろ bir şeyin arxasını bildirir: 家の後ろ evin arxası.","en":"Nの後ろ means behind something: 家の後ろ, behind the house.","ru":"Nの後ろ означает «позади чего-либо»: 家の後ろ, за домом."}},"心":{"b":"心 (こころ)","p":"n","m":{"az":"ürək, qəlb, könül","en":"heart, mind, spirit","ru":"сердце, душа, разум"},"n":{"az":"Burada fiziki orqandan çox hiss və düşüncəni bildirir.","en":"Usually refers to feelings or the mind rather than the physical organ.","ru":"Обычно обозначает чувства или душу, а не физический орган."}},"心配":{"b":"心配 (しんぱい)","p":"n","m":{"az":"narahatlıq, qayğı","en":"worry, concern","ru":"беспокойство, тревога"},"n":{"az":"心配する “narahat olmaq” deməkdir; 心配な şəklində na-sifəti kimi də işlənir.","en":"心配する means “worry”; 心配な is also used as a na-adjective.","ru":"心配する означает «беспокоиться»; форма 心配な также употребляется как прилагательное на な."}},"必ず":{"b":"必ず (かならず)","p":"ad","m":{"az":"mütləq; hökmən","en":"certainly; without fail","ru":"обязательно; непременно"},"n":{"az":"Güclü əminlik və ya tələb bildirir: 必ず帰ります.","en":"Expresses certainty or a firm requirement: 必ず帰ります.","ru":"Выражает уверенность или обязательность: 必ず帰ります."}},"怖い":{"b":"怖い (こわい)","p":"ai","m":{"az":"qorxulu, vahiməli","en":"scary, frightening","ru":"страшный, пугающий"},"n":{"az":"い-sifətdir: 怖い話 = qorxulu hekayə; 怖くない = qorxulu deyil.","en":"An i-adjective: 怖い話 = scary story; 怖くない = not scary.","ru":"Прилагательное на い: 怖い話 = страшная история; 怖くない = не страшно."}},"思う":{"b":"思う (おもう)","p":"v","m":{"az":"düşünmək, fikirləşmək","en":"to think","ru":"думать"},"n":{"az":"〜と思いました = ...deyə düşündü.","en":"〜と思いました = thought that ...","ru":"〜と思いました = подумал, что ..."}},"急ぐ":{"b":"急ぐ (いそぐ)","p":"v","m":{"az":"tələsmək","en":"hurry","ru":"спешить"},"n":{"az":"て forması 急いで olur.","en":"Its て-form is 急いで.","ru":"Форма на て: 急いで."}},"恐ろしい":{"b":"恐ろしい (おそろしい)","p":"ai","m":{"az":"qorxunc; dəhşətli","en":"terrifying; dreadful","ru":"страшный; ужасный"},"n":{"az":"い-sifətidir; 恐ろしいほど «dəhşətli dərəcədə» mənasında da işlənir.","en":"An i-adjective; 恐ろしいほど can mean \"to a frightening degree.\"","ru":"Прилагательное на い; 恐ろしいほど может означать «до ужаса»."}},"恥ずかしい":{"b":"恥ずかしい (はずかしい)","p":"ai","m":{"az":"utanmış; utancverici","en":"embarrassed; embarrassing","ru":"смущённый; стыдный"},"n":{"az":"い-sifətdir; 恥ずかしくない inkar formasıdır, 恥ずかし isə köküdür.","en":"An i-adjective; 恥ずかしくない is its negative form, and 恥ずかし is its stem.","ru":"Прилагательное на い; 恥ずかしくない отрицательная форма, а 恥ずかし основа."}},"悲しい":{"b":"悲しい (かなしい)","p":"ai","m":{"az":"kədərli","en":"sad","ru":"грустный"},"n":{"az":"İ-sifətidir; 悲しく zərf formasıdır və “kədərli şəkildə” mənasını verir.","en":"An i-adjective; 悲しく is its adverbial form, meaning “sadly.”","ru":"Прилагательное на い; 悲しく является наречной формой со значением «грустно»."}},"手":{"b":"手 (て)","p":"n","m":{"az":"əl","en":"hand","ru":"рука"}},"手伝う":{"b":"手伝う (てつだう)","p":"v","m":{"az":"kömək etmək","en":"to help; to assist","ru":"помогать"},"n":{"az":"手伝いましょう təklif bildirir: kömək edim.","en":"手伝いましょう offers help: shall I help?","ru":"手伝いましょう выражает предложение помощи: давайте помогу."}},"抱く":{"b":"抱く (だく)","p":"v","m":{"az":"qucaqlamaq; qucaqda tutmaq","en":"to hug; to hold in one's arms","ru":"обнимать; держать на руках"},"n":{"az":"抱く qucaqlamaq mənasında だく, hiss bəsləmək mənasında isə çox vaxt いだく oxunur.","en":"抱く is read だく for holding someone and often いだく for harboring feelings.","ru":"抱く читается だく при объятии и часто いだく при обозначении чувств."}},"拍手":{"b":"拍手 (はくしゅ)","p":"n","m":{"az":"alqış","en":"applause, clapping","ru":"аплодисменты"},"n":{"az":"拍手する - alqışlamaq.","en":"拍手する means to clap or applaud.","ru":"拍手する означает аплодировать."}},"持つ":{"b":"持つ (もつ)","p":"v","m":{"az":"tutmaq, daşımaq; sahib olmaq","en":"to hold, to carry; to have","ru":"держать, нести; иметь"},"n":{"az":"かばんを持って = çantanı tutub (te-forması: hərəkətlər ardıcıllığı).","en":"かばんを持って = holding a bag.","ru":"かばんを持って = держа сумку."}},"振る":{"b":"振る (ふる)","p":"v","m":{"az":"yelləmək; silkələmək","en":"wave; shake","ru":"махать; трясти"},"n":{"az":"手を振る əl yelləmək, 首を振る isə başı yelləmək deməkdir.","en":"手を振る means to wave a hand; 首を振る means to shake one's head.","ru":"手を振る означает махать рукой, а 首を振る качать головой."}},"掃除":{"b":"掃除 (そうじ)","p":"n","m":{"az":"təmizlik","en":"cleaning","ru":"уборка"},"n":{"az":"掃除する təmizlik etmək deməkdir.","en":"掃除する means to clean.","ru":"掃除する означает делать уборку."}},"握る":{"b":"握る (にぎる)","p":"v","m":{"az":"(əlində) tutmaq, sıxmaq","en":"to grasp, hold","ru":"сжимать, держать"},"n":{"az":"手をにぎる = əlini tutmaq.","en":"手をにぎる = hold someone's hand.","ru":"手をにぎる = взять за руку."}},"教える":{"b":"教える (おしえる)","p":"v","m":{"az":"öyrətmək; demək (məlumat vermək)","en":"to teach; to tell","ru":"учить; сообщать"},"n":{"az":"名前を教えてください = adınızı deyin (zəhmət olmasa).","en":"名前を教えてください = please tell me your name.","ru":"名前を教えてください = скажите, пожалуйста, имя."}},"数字":{"b":"数字 (すうじ)","p":"n","m":{"az":"rəqəm; ədədi işarə","en":"digit; numeral","ru":"цифра; числовой знак"}},"日":{"b":"日 (ひ)","p":"n","m":{"az":"gün; günəş","en":"day; sun","ru":"день; солнце"},"n":{"az":"Müstəqil söz kimi çox vaxt ひ oxunur; tarixlərdə və birləşmələrdə oxunuşu dəyişir.","en":"Usually read ひ as a standalone word; its reading changes in dates and compounds.","ru":"Как отдельное слово обычно читается ひ; в датах и сложных словах чтение меняется."}},"日中":{"b":"日中 (にっちゅう)","p":"n","m":{"az":"gündüz vaxtı","en":"daytime; during the day","ru":"дневное время; днём"},"n":{"az":"にっちゅう oxunuşunda gündüzü bildirir; にっちゅう həm də Yaponiya-Çin əlaqələrini ifadə edə bilər.","en":"Usually means daytime here; the same reading can also refer to Japan-China relations.","ru":"Здесь означает дневное время; то же чтение может обозначать японо-китайские отношения."}},"早い":{"b":"早い (はやい)","p":"ai","m":{"az":"erkən; tez","en":"early","ru":"ранний; рано"},"n":{"az":"い-sifətidir; 早く zərf formasıdır, sürət mənasında isə 速い yazılır.","en":"An い-adjective; 早く is its adverb form, while 速い refers to speed.","ru":"い-прилагательное; 早く является наречной формой, а 速い обозначает скорость."}},"早く":{"b":"早い (はやい)","p":"ad","m":{"az":"tez; erkən","en":"quickly; early","ru":"быстро; рано"},"n":{"az":"早い sifətinin zərf formasıdır; «tez» və ya «erkən» mənası kontekstdən asılıdır.","en":"Adverbial form of 早い; it means quickly or early depending on context.","ru":"Наречная форма 早い; означает «быстро» или «рано» в зависимости от контекста."}},"明るい":{"b":"明るい (あかるい)","p":"ai","m":{"az":"işıqlı, parlaq","en":"bright","ru":"светлый, яркий"},"n":{"az":"明るく光る = parlaq işıq saçmaq.","en":"明るく光る = shine brightly.","ru":"明るく光る = ярко светиться."}},"明日":{"b":"明日 (あした)","p":"n","m":{"az":"sabah","en":"tomorrow","ru":"завтра"},"n":{"az":"Vaxt bildirəndə adətən に işlənmir: 明日行きます.","en":"Usually takes no に as a time expression: 明日行きます.","ru":"При обозначении времени обычно употребляется без に: 明日行きます."}},"昼休み":{"b":"昼休み (ひるやすみ)","p":"n","m":{"az":"nahar fasiləsi, günorta tənəffüsü","en":"lunch break, midday recess","ru":"обеденный перерыв, большая перемена"}},"昼間":{"b":"昼間 (ひるま)","p":"n","m":{"az":"gündüz; gündüz vaxtı","en":"daytime","ru":"дневное время; днём"}},"時":{"b":"時 (とき)","p":"n","m":{"az":"vaxt, zaman","en":"time, occasion","ru":"время, момент"},"n":{"az":"時 “vaxt” mənasında とき, saat bildirən rəqəmdən sonra isə じ oxunur: 三時 “saat üç”.","en":"時 is read とき for “time” but じ after a number indicating the hour: 三時 “three o'clock.”","ru":"時 читается とき в значении «время», но じ после числа, обозначающего час: 三時 «три часа»."}},"暗い":{"b":"暗い (くらい)","p":"ai","m":{"az":"qaranlıq, tutqun","en":"dark, gloomy","ru":"тёмный, мрачный"},"n":{"az":"İ-sifətidir və həm zəif işığı, həm də tutqun əhvalı bildirə bilər.","en":"An i-adjective that can describe low light or a gloomy mood.","ru":"Прилагательное на い, описывающее слабое освещение или мрачное настроение."}},"書類":{"b":"書類 (しょるい)","p":"n","m":{"az":"sənədlər; sənəd","en":"documents; paperwork","ru":"документы; бумаги"}},"月":{"b":"月 (つき)","p":"n","m":{"az":"Ay","en":"the Moon","ru":"Луна"},"n":{"az":"Təqvim ayı mənasında がつ/げつ oxunur.","en":"As 'month' it is read がつ/げつ.","ru":"В значении 'месяц' читается がつ/げつ."}},"朝":{"b":"朝 (あさ)","p":"n","m":{"az":"səhər","en":"morning","ru":"утро"}},"木":{"b":"木 (き)","p":"n","m":{"az":"ağac; taxta","en":"tree; wood","ru":"дерево; древесина"}},"本当":{"b":"本当 (ほんとう)","p":"n","m":{"az":"həqiqət, doğru","en":"truth, reality","ru":"правда, истина"},"n":{"az":"本当です doğru deməkdir, 本当に isə həqiqətən mənasını verir.","en":"本当です means it is true, while 本当に means really.","ru":"本当です означает это правда, а 本当に - действительно."}},"村":{"b":"村 (むら)","p":"n","m":{"az":"kənd","en":"village","ru":"деревня"}},"村中":{"b":"村中 (むらじゅう)","p":"n","m":{"az":"bütün kənd; kəndin hər yeri","en":"the whole village; throughout the village","ru":"вся деревня; по всей деревне"},"n":{"az":"中 burada じゅう oxunur və «bütün» mənasını verir.","en":"中 is read じゅう here and means \"throughout\" or \"all of.\"","ru":"中 здесь читается じゅう и означает «по всей» или «вся»."}},"来る":{"b":"来る (くる)","p":"v","m":{"az":"gəlmək","en":"to come","ru":"приходить"},"n":{"az":"Qeyri-müntəzəm feildir: 来ます (kimasu), 来た (kita), 来て (kite). 〜から来ました = ...-dan gəlmişəm. 迎えに来る = aparmağa gəlmək.","en":"Irregular verb: 来ます, 来た (kita), 来て (kite). 〜から来ました = I come from ...","ru":"Неправильный глагол: 来ます, 来た (kita), 来て (kite). 〜から来ました = я из ..."}},"森":{"b":"森 (もり)","p":"nm","m":{"az":"Mori (soyad; mənası 'meşə')","en":"Mori (surname; means 'forest')","ru":"Мори (фамилия; значит 'лес')"}},"楽しい":{"b":"楽しい (たのしい)","p":"ai","m":{"az":"əyləncəli; xoş","en":"fun; enjoyable","ru":"весёлый; приятный"},"n":{"az":"İ-sifətdir; 楽しく onun zərf formasıdır.","en":"An i-adjective; 楽しく is its adverbial form.","ru":"И-прилагательное; 楽しく является его наречной формой."}},"横":{"b":"横 (よこ)","p":"n","m":{"az":"yan; böyür","en":"side; beside","ru":"бок; рядом"},"n":{"az":"Nの横 = N-in yanı; üfüqi istiqamət mənası da var.","en":"Nの横 means beside N; 横 can also refer to a horizontal direction.","ru":"Nの横 означает рядом с N; 横 также обозначает горизонтальное направление."}},"次":{"b":"次 (つぎ)","p":"n","m":{"az":"növbəti; sonrakı","en":"next; following","ru":"следующий"},"n":{"az":"İsimdən əvvəl 次の, ardıcıllıq bildirmək üçün 次に işlənir.","en":"Use 次の before a noun and 次に to mean next in a sequence.","ru":"Перед существительным используется 次の, а для следующего шага 次に."}},"歌":{"b":"歌 (うた)","p":"n","m":{"az":"mahnı","en":"song","ru":"песня"}},"歌う":{"b":"歌う (うたう)","p":"v","m":{"az":"oxumaq; mahnı oxumaq","en":"to sing","ru":"петь"},"n":{"az":"歌を歌う = mahnı oxumaq; て-forması 歌って-dir.","en":"歌を歌う means to sing a song; its て-form is 歌って.","ru":"歌を歌う означает петь песню; て-форма: 歌って."}},"歌わす":{"b":"歌わす (うたわす)","p":"v","m":{"az":"oxutmaq; mahnı oxumağa məcbur etmək","en":"make someone sing; let someone sing","ru":"заставлять петь; позволять петь"},"n":{"az":"歌う felinin danışıqda işlənən icbar formasıdır; 歌わされました «oxumağa məcbur edildim» deməkdir.","en":"Colloquial causative of 歌う; 歌わされました means \"was made to sing.\"","ru":"Разговорная побудительная форма 歌う; 歌わされました означает «заставили петь»."}},"毎日":{"b":"毎日 (まいにち)","p":"n","m":{"az":"hər gün","en":"every day","ru":"каждый день"}},"毎朝":{"b":"毎朝 (まいあさ)","p":"n","m":{"az":"hər səhər","en":"every morning","ru":"каждое утро"},"n":{"az":"Vaxt bildirəndə に işlənmir: 毎朝働きます.","en":"Takes no に as a time expression: 毎朝働きます.","ru":"При обозначении времени употребляется без に: 毎朝働きます."}},"気":{"b":"気 (き)","p":"n","m":{"az":"ruh, əhval, niyyət","en":"spirit, mood, intention","ru":"дух, настроение, намерение"},"n":{"az":"気をつける = diqqətli olmaq; 気になる = maraqlandırmaq və ya narahat etmək.","en":"気をつける = to be careful; 気になる = to be curious or concerned.","ru":"気をつける = быть осторожным; 気になる = интересовать или беспокоить."}},"水":{"b":"水 (みず)","p":"n","m":{"az":"su","en":"water","ru":"вода"},"n":{"az":"水 adətən soyuq və ya otaq temperaturunda suyu, お湯 isə isti suyu bildirir.","en":"水 usually means cold or room-temperature water; お湯 means hot water.","ru":"水 обычно обозначает холодную воду или воду комнатной температуры, а お湯 означает горячую воду."}},"治す":{"b":"治す (なおす)","p":"v","m":{"az":"sağaltmaq; müalicə etmək","en":"cure; heal","ru":"лечить; исцелять"},"n":{"az":"Təsirli feldir, təsirsiz qarşılığı 治る-dur; 治していただけませんか nəzakətli xahişdir.","en":"Transitive verb paired with 治る; 治していただけませんか is a polite request for treatment.","ru":"Переходный глагол с непереходной парой 治る; 治していただけませんか является вежливой просьбой вылечить."}},"泣く":{"b":"泣く (なく)","p":"v","m":{"az":"ağlamaq","en":"to cry","ru":"плакать"}},"消える":{"b":"消える (きえる)","p":"v","m":{"az":"sönmək, yox olmaq","en":"to go out, disappear","ru":"гаснуть, исчезать"},"n":{"az":"消えそうになる = az qala sönmək.","en":"消えそうになる = be about to go out.","ru":"消えそうになる = вот-вот погаснуть."}},"準備":{"b":"準備 (じゅんび)","p":"n","m":{"az":"hazırlıq","en":"preparation","ru":"подготовка"},"n":{"az":"準備する hazırlaşmaq, 準備ができる isə hazır olmaq deməkdir.","en":"準備する means to prepare; 準備ができる means to be ready.","ru":"準備する означает готовиться, а 準備ができる быть готовым."}},"父親":{"b":"父親 (ちちおや)","p":"n","m":{"az":"ata","en":"father","ru":"отец"}},"狐":{"b":"狐 (きつね)","p":"n","m":{"az":"tülkü","en":"fox","ru":"лиса"}},"現れる":{"b":"現れる (あらわれる)","p":"v","m":{"az":"görünmək; ortaya çıxmaq","en":"appear; emerge","ru":"появляться"},"n":{"az":"Təsirsiz feldir; 現す nəyisə üzə çıxarmaq və ya göstərmək deməkdir.","en":"An intransitive verb; 現す means to reveal or show something.","ru":"Непереходный глагол; 現す означает обнаружить или показать что-либо."}},"男":{"b":"男 (おとこ)","p":"n","m":{"az":"kişi","en":"man, male","ru":"мужчина"},"n":{"az":"Nəzakətli gündəlik nitqdə kişi üçün çox vaxt 男の人 işlənir.","en":"男の人 is often used for a man in polite everyday speech.","ru":"В вежливой повседневной речи о мужчине часто говорят 男の人."}},"男の子":{"b":"男の子 (おとこのこ)","p":"n","m":{"az":"oğlan","en":"boy","ru":"мальчик"}},"町":{"b":"町 (まち)","p":"n","m":{"az":"şəhərcik; məhəllə","en":"town; neighborhood","ru":"городок; квартал"}},"疲れる":{"b":"疲れる (つかれる)","p":"v","m":{"az":"yorulmaq","en":"to get tired","ru":"уставать"},"n":{"az":"疲れました - yoruldum; 疲れています - yorğunam.","en":"疲れました means got tired; 疲れています means am tired.","ru":"疲れました означает устал; 疲れています - я устал и сейчас чувствую усталость."}},"発表":{"b":"発表 (はっぴょう)","p":"n","m":{"az":"təqdimat; elan; çıxış","en":"presentation; announcement","ru":"презентация; объявление; выступление"},"n":{"az":"発表する təqdim etmək və ya nəticəni elan etməkdir.","en":"発表する means to present or announce something.","ru":"発表する означает выступать с презентацией или объявлять результат."}},"百回":{"b":"百回 (ひゃっかい)","p":"nu","m":{"az":"yüz dəfə","en":"one hundred times","ru":"сто раз"},"n":{"az":"百回 ひゃっかい oxunur; 回 sayğacında bəzi rəqəmlər səs dəyişikliyi yaradır.","en":"Read ひゃっかい; the 回 counter has sound changes with certain numbers.","ru":"Читается ひゃっかい; счётный суффикс 回 меняет звучание с некоторыми числами."}},"目":{"b":"目 (め)","p":"n","m":{"az":"göz","en":"eye","ru":"глаз"}},"着く":{"b":"着く (つく)","p":"v","m":{"az":"çatmaq; yetişmək","en":"to arrive; to reach","ru":"прибывать; добираться"},"n":{"az":"Yerə çatmağı bildirir və adətən に ilə işlənir: 駅に着く.","en":"Indicates arrival at a place and usually takes に: 駅に着く.","ru":"Обозначает прибытие в место и обычно употребляется с に: 駅に着く."}},"知る":{"b":"知る (しる)","p":"v","m":{"az":"bilmək, tanımaq","en":"to know","ru":"знать"},"n":{"az":"Bilmirəm demək üçün 知りません deyilir. 知りませんでした = bilmirdilər (nəzakətli inkar, keçmiş).","en":"Negative: 知りません. 知りませんでした = did not know.","ru":"Отрицание: 知りません. 知りませんでした = не знали."}},"確認":{"b":"確認 (かくにん)","p":"n","m":{"az":"yoxlama; təsdiqləmə","en":"confirmation; checking","ru":"проверка; подтверждение"},"n":{"az":"確認する «yoxlamaq» və ya «dəqiqləşdirmək» deməkdir.","en":"確認する means \"to check\" or \"to confirm.\"","ru":"確認する означает «проверять» или «подтверждать»."}},"私":{"b":"私 (わたし)","p":"pr","m":{"az":"mən","en":"I; me","ru":"я; меня"},"n":{"az":"Nəzakətli, neytral birinci şəxs əvəzliyidir və kontekstdən aydın olduqda buraxılır.","en":"A polite, neutral first-person pronoun, often omitted when clear from context.","ru":"Вежливое нейтральное местоимение первого лица, часто опускаемое, если понятно из контекста."}},"空":{"b":"空 (そら)","p":"n","m":{"az":"göy, səma","en":"sky","ru":"небо"}},"立たす":{"b":"立たす (たたす)","p":"v","m":{"az":"ayağa qaldırmaq; ayaq üstə durmağa məcbur etmək","en":"make someone stand","ru":"заставлять стоять"},"n":{"az":"立つ felinin danışıq icbar formasıdır; 立たされ «ayaq üstə durmağa məcbur edilərək» deməkdir.","en":"Colloquial causative of 立つ; 立たされ is a causative-passive connecting form.","ru":"Разговорная побудительная форма 立つ; 立たされ является соединительной формой побудительно-страдательного залога."}},"立つ":{"b":"立つ (たつ)","p":"v","m":{"az":"dayanmaq, ayağa qalxmaq","en":"to stand","ru":"стоять, вставать"}},"竹":{"b":"竹 (たけ)","p":"n","m":{"az":"bambuk","en":"bamboo","ru":"бамбук"}},"笑う":{"b":"笑う (わらう)","p":"v","m":{"az":"gülmək, gülümsəmək","en":"to laugh, to smile","ru":"смеяться, улыбаться"},"n":{"az":"笑うと = gülümsəyəndə (feil + と = 'edəndə').","en":"笑うと = when he smiled.","ru":"笑うと = когда он улыбался."}},"答える":{"b":"答える (こたえる)","p":"v","m":{"az":"cavab vermək","en":"to answer","ru":"отвечать"}},"約束":{"b":"約束 (やくそく)","p":"n","m":{"az":"söz; görüş razılaşması","en":"promise; appointment","ru":"обещание; договорённость о встрече"},"n":{"az":"約束する = söz vermək və ya görüş barədə razılaşmaq.","en":"約束する means to promise or arrange to meet.","ru":"約束する означает обещать или договариваться о встрече."}},"紙":{"b":"紙 (かみ)","p":"n","m":{"az":"kağız","en":"paper","ru":"бумага"}},"終わる":{"b":"終わる (おわる)","p":"v","m":{"az":"bitmək; sona çatmaq","en":"to end; to finish","ru":"заканчиваться"},"n":{"az":"Adətən təsirsizdir: 試験が終わります; təsirli qarşılığı 終える-dir.","en":"Usually intransitive: 試験が終わります; its transitive partner is 終える.","ru":"Обычно непереходный: 試験が終わります; переходная пара: 終える."}},"絵":{"b":"絵 (え)","p":"n","m":{"az":"şəkil, rəsm","en":"picture, drawing","ru":"картина, рисунок"}},"絶対":{"b":"絶対 (ぜったい)","p":"n","m":{"az":"qətilik; mütləqlik","en":"absoluteness; certainty","ru":"абсолютность; безусловность"},"n":{"az":"絶対に müsbət cümlədə «mütləq», inkarla isə «heç bir halda» deməkdir.","en":"絶対に means \"definitely\" in affirmative sentences and \"under no circumstances\" with negatives.","ru":"絶対に означает «обязательно» в утвердительных предложениях и «ни в коем случае» с отрицанием."}},"練習":{"b":"練習 (れんしゅう)","p":"n","m":{"az":"məşq, praktika","en":"practice, training","ru":"практика, тренировка"},"n":{"az":"練習する = məşq etmək; ピアノの練習 = piano məşqi.","en":"練習する = to practice; ピアノの練習 = piano practice.","ru":"練習する = тренироваться; ピアノの練習 = занятие на пианино."}},"翌朝":{"b":"翌朝 (よくあさ)","p":"n","m":{"az":"ertəsi səhər","en":"the following morning","ru":"на следующее утро"}},"考える":{"b":"考える (かんがえる)","p":"v","m":{"az":"düşünmək, fikirləşmək, nəzərdən keçirmək","en":"to think, to consider","ru":"думать, обдумывать, рассматривать"},"n":{"az":"〜について考える - bir mövzu haqqında düşünmək.","en":"〜について考える means to think about a topic.","ru":"〜について考える означает думать о какой-либо теме."}},"者":{"b":"者 (もの)","p":"n","m":{"az":"adam; şəxs","en":"person; individual","ru":"человек; лицо"},"n":{"az":"もの oxunuşu insanı bildirir; 者 mürəkkəb sözlərdə çox vaxt しゃ oxunur.","en":"Read もの as a standalone word; often read しゃ in compounds.","ru":"Отдельно читается もの; в сложных словах часто читается しゃ."}},"聞く":{"b":"聞く (きく)","p":"v","m":{"az":"soruşmaq; eşitmək, qulaq asmaq","en":"to ask; to hear, listen","ru":"спрашивать; слушать"},"n":{"az":"Burada 'soruşmaq': 「…」と聞くと = «…» deyə soruşanda.","en":"Here 'ask': 「…」と聞くと = when she asked \"…\".","ru":"Здесь 'спросить': 「…」と聞くと = когда спросила «…»."}},"聞こえる":{"b":"聞こえる (きこえる)","p":"v","m":{"az":"eşidilmək","en":"to be audible; to hear","ru":"быть слышным; слышаться"},"n":{"az":"Səs が ilə göstərilir: 歌が聞こえる; bu, qəsdən qulaq asmaq deyil, səsin qulağa çatmasıdır.","en":"The sound takes が: 歌が聞こえる; it describes audibility rather than deliberate listening.","ru":"Звук обозначается через が: 歌が聞こえる; речь о слышимости, а не о намеренном слушании."}},"肩":{"b":"肩 (かた)","p":"n","m":{"az":"çiyin","en":"shoulder","ru":"плечо"}},"自分":{"b":"自分 (じぶん)","p":"n","m":{"az":"öz, özü","en":"oneself","ru":"сам, свой"},"n":{"az":"自分の名前 = öz adı.","en":"自分の名前 = one's own name.","ru":"自分の名前 = своё имя."}},"舞台":{"b":"舞台 (ぶたい)","p":"n","m":{"az":"səhnə","en":"stage","ru":"сцена"},"n":{"az":"舞台に立つ = səhnəyə çıxmaq.","en":"舞台に立つ = to stand or perform on stage.","ru":"舞台に立つ = выйти на сцену."}},"若い":{"b":"若い (わかい)","p":"ai","m":{"az":"gənc, cavan","en":"young","ru":"молодой"},"n":{"az":"İ-sifətidir: 若い人 “gənc insan”.","en":"An i-adjective: 若い人 means “a young person.”","ru":"Прилагательное на い: 若い人 «молодой человек»."}},"薬":{"b":"薬 (くすり)","p":"n","m":{"az":"dərman","en":"medicine","ru":"лекарство"},"n":{"az":"薬を飲む dərman qəbul etmək deməkdir, hərfi mənada içmək işlənir.","en":"薬を飲む means to take medicine, literally using the verb drink.","ru":"薬を飲む означает принимать лекарство, буквально используется глагол пить."}},"行く":{"b":"行く (いく)","p":"v","m":{"az":"getmək","en":"go","ru":"идти; ехать"},"n":{"az":"İstiqamət に və ya へ ilə göstərilir; て forması 行って, keçmiş forması 行った olur.","en":"The destination takes に or へ; its irregular forms are 行って and 行った.","ru":"Направление обозначается に или へ; особые формы: 行って и 行った."}},"見せる":{"b":"見せる (みせる)","p":"v","m":{"az":"göstərmək","en":"show","ru":"показывать"},"n":{"az":"人に物を見せる kiməsə nəyisə göstərmək quruluşudur.","en":"Use 人に物を見せる to show something to someone.","ru":"Конструкция 人に物を見せる означает показать что-либо кому-либо."}},"見つける":{"b":"見つける (みつける)","p":"v","m":{"az":"tapmaq; aşkar etmək","en":"find; discover","ru":"находить; обнаруживать"},"n":{"az":"Təsirli feldir; 見つかる tapılmaq deməkdir.","en":"A transitive verb; 見つかる means to be found.","ru":"Переходный глагол; 見つかる означает найтись."}},"見る":{"b":"見る (みる)","p":"v","m":{"az":"baxmaq, görmək","en":"to see, to look","ru":"смотреть, видеть"},"n":{"az":"月を見てください = Aya baxın.","en":"月を見てください = please look at the moon.","ru":"月を見てください = смотрите на луну."}},"触る":{"b":"触る (さわる)","p":"v","m":{"az":"toxunmaq","en":"to touch","ru":"трогать; прикасаться"},"n":{"az":"Adətən N に触る şəklində işlənir: ボタンに触る.","en":"Usually takes に: ボタンに触る means to touch a button.","ru":"Обычно используется с に: ボタンに触る означает касаться кнопки."}},"言う":{"b":"言う (いう)","p":"v","m":{"az":"demək","en":"to say","ru":"сказать, говорить"},"n":{"az":"「…」と言いました = «…» dedi. Oxunuşu 'iu' kimi səslənir.","en":"「…」と言いました = said \"…\". Pronounced 'yuu'.","ru":"「…」と言いました = сказал «…»."}},"課長":{"b":"課長 (かちょう)","p":"n","m":{"az":"şöbə rəhbəri; bölmə müdiri","en":"section chief; section manager","ru":"начальник отдела; заведующий сектором"},"n":{"az":"Adətən 部長-dan aşağı rəhbər vəzifəsidir.","en":"Usually a managerial rank below 部長.","ru":"Обычно руководящая должность ниже 部長."}},"赤い":{"b":"赤い (あかい)","p":"ai","m":{"az":"qırmızı","en":"red","ru":"красный"},"n":{"az":"赤く光る = qırmızı parlamaq (い → く: zərf).","en":"赤く光る = shine red (い → く: adverb).","ru":"赤く光る = светиться красным (い → く: наречие)."}},"走る":{"b":"走る (はしる)","p":"v","m":{"az":"qaçmaq","en":"run","ru":"бежать"},"n":{"az":"る ilə bitsə də birinci qrup feldir; 走らせる qaçırmaq, 車を走らせる isə maşını sürmək deməkdir.","en":"Despite ending in る, it is a group 1 verb; 走らせる means make run, and 車を走らせる means drive a car.","ru":"Несмотря на る, это глагол первой группы; 走らせる означает заставить бежать, а 車を走らせる вести машину."}},"足":{"b":"足 (あし)","p":"n","m":{"az":"ayaq","en":"foot; leg","ru":"нога; ступня"},"n":{"az":"Kontekstdən asılı olaraq ayağın pəncəsini və ya bütün aşağı ətrafı bildirir.","en":"Can mean the foot or the whole leg, depending on context.","ru":"В зависимости от контекста обозначает ступню или всю ногу."}},"通う":{"b":"通う (かよう)","p":"v","m":{"az":"mütəmadi gedib-gəlmək; davam etmək","en":"commute; attend regularly","ru":"регулярно ходить; посещать"},"n":{"az":"学校に通う «məktəbə davam etmək», 通っていました isə keçmişdə davam edən vərdişi bildirir.","en":"学校に通う means \"attend school\"; 通っていました describes past regular attendance.","ru":"学校に通う означает «ходить в школу»; 通っていました описывает регулярное посещение в прошлом."}},"遅く":{"b":"遅い (おそい)","p":"ad","m":{"az":"gec; yavaş","en":"late; slowly","ru":"поздно; медленно"},"n":{"az":"遅い sifətinin zərf formasıdır; vaxt və sürət mənaları kontekstdən asılıdır.","en":"Adverbial form of 遅い; it refers to lateness or slowness depending on context.","ru":"Наречная форма 遅い; обозначает опоздание или медленность в зависимости от контекста."}},"遊ぶ":{"b":"遊ぶ (あそぶ)","p":"v","m":{"az":"oynamaq; əylənmək","en":"to play; to have fun","ru":"играть; развлекаться"},"n":{"az":"て-forması 遊んで-dir; 友達と遊ぶ = dostlarla oynamaq və ya vaxt keçirmək.","en":"Its て-form is 遊んで; 友達と遊ぶ means to play or spend time with friends.","ru":"て-форма: 遊んで; 友達と遊ぶ означает играть или проводить время с друзьями."}},"運ぶ":{"b":"運ぶ (はこぶ)","p":"v","m":{"az":"daşımaq","en":"to carry, to transport","ru":"нести, перевозить"},"n":{"az":"て forması 運んで-dir; 荷物を運ぶ yük daşımaq deməkdir.","en":"The て-form is 運んで; 荷物を運ぶ means to carry luggage.","ru":"Форма на て: 運んで; 荷物を運ぶ означает нести багаж."}},"道":{"b":"道 (みち)","p":"n","m":{"az":"yol","en":"road, path","ru":"дорога"}},"道場":{"b":"道場 (どうじょう)","p":"n","m":{"az":"döyüş sənətləri məşq zalı; dojo","en":"martial arts training hall; dojo","ru":"зал боевых искусств; додзё"}},"部屋":{"b":"部屋 (へや)","p":"n","m":{"az":"otaq","en":"room","ru":"комната"}},"重い":{"b":"重い (おもい)","p":"ai","m":{"az":"ağır","en":"heavy","ru":"тяжёлый"},"n":{"az":"い sifətidir, 重くて bağlayıcı formadır: 重くて持てません.","en":"An i-adjective, with 重くて linking clauses: 重くて持てません means it is too heavy to carry.","ru":"Прилагательное на い, 重くて связывает части предложения: 重くて持てません - слишком тяжёлый, не могу нести."}},"金曜":{"b":"金曜 (きんよう)","p":"n","m":{"az":"cümə","en":"Friday","ru":"пятница"},"n":{"az":"金曜日 sözünün qısa formasıdır.","en":"Short for 金曜日.","ru":"Сокращение от 金曜日."}},"長い":{"b":"長い (ながい)","p":"ai","m":{"az":"uzun","en":"long","ru":"длинный; долгий"},"n":{"az":"İ-sifətdir və həm uzunluğu, həm də müddəti təsvir edir.","en":"An i-adjective describing both length and duration.","ru":"И-прилагательное, описывающее длину и длительность."}},"開ける":{"b":"開ける (あける)","p":"v","m":{"az":"açmaq","en":"to open","ru":"открывать"},"n":{"az":"開けると = açanda.","en":"開けると = when he opened.","ru":"開けると = когда открыл."}},"階段":{"b":"階段 (かいだん)","p":"n","m":{"az":"pilləkən","en":"stairs, staircase","ru":"лестница"}},"隣":{"b":"隣 (となり)","p":"n","m":{"az":"yan, qonşuluq","en":"next door, next to","ru":"соседство, рядом"},"n":{"az":"Nの隣 birbaşa N-in yanındakı yeri bildirir.","en":"Nの隣 refers to a place directly next to N.","ru":"Nの隣 обозначает место непосредственно рядом с N."}},"集まる":{"b":"集まる (あつまる)","p":"v","m":{"az":"toplaşmaq; yığışmaq","en":"to gather; to assemble","ru":"собираться; сходиться"},"n":{"az":"自動詞-dir; 集める isə nəyisə toplamaqdır.","en":"An intransitive verb; 集める means to collect something.","ru":"Непереходный глагол; 集める означает собирать что-либо."}},"雲":{"b":"雲 (くも)","p":"n","m":{"az":"bulud","en":"cloud","ru":"облако"}},"青い":{"b":"青い (あおい)","p":"ai","m":{"az":"mavi, göy","en":"blue","ru":"синий, голубой"}},"静か":{"b":"静か (しずか)","p":"an","m":{"az":"sakit, səssiz","en":"quiet","ru":"тихий"},"n":{"az":"静かになる = sakitləşmək (na-sifət + に + なる).","en":"静かになる = become quiet.","ru":"静かになる = стать тихим."}},"頭":{"b":"頭 (あたま)","p":"n","m":{"az":"baş","en":"head","ru":"голова"}},"頼む":{"b":"頼む (たのむ)","p":"v","m":{"az":"xahiş etmək; sifariş vermək","en":"to request; to order","ru":"просить; заказывать"},"n":{"az":"頼みました keçmiş nəzakətli formadır.","en":"頼みました is the polite past form.","ru":"頼みました - вежливая форма прошедшего времени."}},"顔":{"b":"顔 (かお)","p":"n","m":{"az":"üz, sifət","en":"face","ru":"лицо"}},"風":{"b":"風 (かぜ)","p":"n","m":{"az":"külək","en":"wind","ru":"ветер"}},"飛び乗る":{"b":"飛び乗る (とびのる)","p":"v","m":{"az":"sıçrayıb minmək; tullanıb üstünə çıxmaq","en":"jump onto; leap aboard","ru":"запрыгивать на; вскакивать в"},"n":{"az":"飛ぶ və 乗る fellərindən yaranıb; nəqliyyat vasitəsinə minəndə に işlənir.","en":"Compound of 飛ぶ and 乗る; use に for the vehicle boarded.","ru":"Сложный глагол из 飛ぶ и 乗る; транспортное средство обозначается частицей に."}},"飛び出す":{"b":"飛び出す (とびだす)","p":"v","m":{"az":"sıçrayıb çıxmaq; qəfil bayıra atılmaq","en":"jump out; dash out","ru":"выпрыгивать; выскакивать"},"n":{"az":"飛ぶ və 出す birləşməsidir; qəfil çıxma və ya hərəkətə başlama bildirir.","en":"Compound of 飛ぶ and 出す; expresses sudden movement outward.","ru":"Сложный глагол из 飛ぶ и 出す; обозначает резкое движение наружу."}},"飛ぶ":{"b":"飛ぶ (とぶ)","p":"v","m":{"az":"uçmaq, havada hərəkət etmək","en":"to fly","ru":"летать, лететь"},"n":{"az":"Təsirsiz feldir, 飛びました nəzakətli keçmiş formadır.","en":"An intransitive verb, with 飛びました as its polite past form.","ru":"Непереходный глагол, 飛びました - его вежливая прошедшая форма."}},"首":{"b":"首 (くび)","p":"n","m":{"az":"boyun; baş","en":"neck; head","ru":"шея; голова"},"n":{"az":"首をふる = başını bulamaq (inkar).","en":"首をふる = shake one's head.","ru":"首をふる = покачать головой."}},"驚く":{"b":"驚く (おどろく)","p":"v","m":{"az":"təəccüblənmək; diksinmək","en":"to be surprised; to be startled","ru":"удивляться; пугаться"},"n":{"az":"Səbəb に ilə göstərilə bilər: 音に驚く = səsdən diksinmək.","en":"The cause can take に: 音に驚く = be startled by a sound.","ru":"Причина может обозначаться через に: 音に驚く = вздрогнуть от звука."}},"高い":{"b":"高い (たかい)","p":"ai","m":{"az":"hündür; baha","en":"high; expensive","ru":"высокий; дорогой"},"n":{"az":"い-sifətdir; 高かった keçmiş formadır.","en":"It is an i-adjective; 高かった is its past form.","ru":"Это i-прилагательное; 高かった - форма прошедшего времени."}},"鳥":{"b":"鳥 (とり)","p":"n","m":{"az":"quş","en":"bird","ru":"птица"}},"鳴く":{"b":"鳴く (なく)","p":"v","m":{"az":"heyvan səsi çıxarmaq; ötmək","en":"make an animal sound; chirp","ru":"издавать голос; петь о птицах"},"n":{"az":"Heyvan və quş səsləri üçün işlənir; insanın ağlaması eyni oxunuşlu 泣く ilə yazılır.","en":"Used for animal and bird cries; human crying is written 泣く with the same reading.","ru":"Употребляется для голосов животных и птиц; человеческий плач записывается 泣く с тем же чтением."}},"黒い":{"b":"黒い (くろい)","p":"ai","m":{"az":"qara","en":"black","ru":"чёрный"},"n":{"az":"İ-sifətdir; rəngin isim forması 黒 olur.","en":"An i-adjective; the noun for the color is 黒.","ru":"И-прилагательное; существительное для цвета: 黒."}}}};